/* بيانات قسم rusul: تُحمَّل عند أول فتح للقسم */
window.RUSUL = {"p":[{"id":"adam","n":"آدم","k":1,"e":"أبو البشر","qw":"أبو البشر وذريته","ulu":0,"hd":"nuh","lb":[["اصطفاه الله",3,33]],"ay":[[2,30,31],[20,121,122]],"s":"خلقه الله من طين بيده، ونفخ فيه من روحه، وأسجد له الملائكة وعلّمه الأسماء، وأسكنه الجنة، فأكل هو وزوجه من الشجرة، ثم تاب الله عليه واجتباه وهداه وأهبطه إلى الأرض.","q":{"w":"ابن كثير","bk":"ibnkathir","s":3,"ay":33,"x":"يُخْبِرُ تَعَالَى أَنَّهُ اخْتَارَ هَذِهِ الْبُيُوتَ عَلَى سَائِرِ أَهْلِ الْأَرْضِ، فَاصْطَفَى آدَمَ، عَلَيْهِ السَّلَامُ، خَلَقَهُ بِيَدِهِ، وَنَفَخَ فِيهِ مِنْ رُوحِهِ، وَأَسْجَدَ لَهُ مَلَائِكَتَهُ، وَعَلَّمَهُ أَسْمَاءَ كُلِّ شَيْءٍ، وَأَسْكَنَهُ الْجَنَّةَ ثُمَّ أَهْبَطَهُ مِنْهَا، لِمَا لَهُ فِي ذَلِكَ مِنَ الْحِكْمَةِ","n":"اصطفاء آدم، وخلقه بيد الله، وإسجاد الملائكة له.","en":"\"Allah the Exalted informs that He chose these houses over all the people of the earth: He chose Adam, peace be upon him, created him with His hand, breathed into him of His spirit, made His angels prostrate to him, taught him the names of all things and settled him in Paradise, then sent him down from it, for the wisdom He had in that.\""},"c":25,"sr":[[36,45],[964,978],[1827,1845],[2089,2093],[2189,2189],[2462,2470],[4040,4054]],"ns":7},{"id":"idris","n":"إدريس","k":2,"e":"الصدّيق النبي","qw":"لم يذكر القرآن قومه","ulu":0,"hd":null,"lb":[["نبي صدّيق",19,56]],"ay":[[19,56,57]],"s":"وصفه الله بأنه صدّيق نبي، ورفعه مكاناً علياً؛ ولم يزد القرآن على ذلك من خبره، ولا سمّى قومه.","q":{"w":"السعدي","bk":"saadi","s":19,"ay":56,"x":"جَمَعَ الله له بين الصِّدِّيقيَّة الجامعة للتصديق التامِّ والعلم الكامل واليقين الثابت والعمل الصالح، وبين اصطفائِهِ لوحيه واختياره لرسالتِهِ","n":"ما جمعه الله له من الصديقية والنبوة.","en":"\"Allah combined for him complete truthfulness, which comprises full belief, perfect knowledge, firm certainty and righteous action, with His choosing him for His revelation and selecting him for His message.\""},"c":2,"sr":[[2305,2306],[2567,2568]],"ns":2},{"id":"nuh","n":"نوح","k":3,"e":"أول رسول إلى أهل الأرض","qw":"قوم أغرقهم الطوفان","ulu":1,"hd":"nuh","lb":[["رسول",26,107]],"ay":[[71,1,4],[29,14]],"s":"دعا قومه ليلاً ونهاراً سراً وجهاراً، ولبث فيهم ألف سنة إلا خمسين عاماً، وأمره الله بصنع الفلك فنجّاه ومن آمن معه وأغرق المكذبين بالطوفان.","q":{"w":"السعدي","bk":"saadi","s":71,"ay":1,"x":"فأخبر تعالى أنَّه أرسل نوحاً إلى قومه رحمةً بهم وإنذاراً [لهم] من عذاب أليم؛ خوفاً من استمرارهم على كفرهم، فيهلكهم [اللَّهُ] هلاكاً أبديًّا، ويعذِّبهم عذاباً سرمديًّا","n":"إرساله إلى قومه رحمةً بهم وإنذاراً.","en":"\"He informs that He sent Nuh to his people as a mercy to them and a warning of a painful punishment, fearing that they would persist in disbelief and He would destroy them with eternal destruction and punish them with everlasting torment.\""},"c":43,"sr":[[1012,1017],[1434,1436],[1497,1521],[2695,2702],[3036,3053],[3862,3869],[4854,4862],[5419,5446]],"ns":8},{"id":"hud","n":"هود","k":4,"e":"أخو عاد","qw":"عاد","ulu":0,"hd":"ad","lb":[["رسول",26,125]],"ay":[[7,65,66],[46,21,22]],"s":"أُرسل إلى عاد، وكانوا أشداء في الخلق وبنوا بكل ريع آية، فكذّبوه فأهلكهم الله بريح صرصر عاتية.","q":{"w":"السعدي","bk":"saadi","s":7,"ay":65,"x":"أرسلنا {إلى عادٍ}: ـ الأولى، الذين كانوا في أرض اليمن ـ {أخاهم}: في النسب {هوداً}: عليه السلام، يدعوهم إلى التوحيد، وينهاهم عن الشرك، والطغيان في الأرض","n":"دعوة هود إلى التوحيد ونهيه عن الشرك والطغيان.","en":"\"We sent to 'Ad, the first 'Ad who lived in the land of Yemen, their brother in lineage, Hud, peace be upon him, calling them to monotheism and forbidding them from shirk and tyranny in the land.\""},"c":10,"sr":[[1018,1025],[1522,1532],[3054,3071],[4530,4535]],"ns":4},{"id":"salih","n":"صالح","k":5,"e":"صاحب الناقة","qw":"ثمود","ulu":0,"hd":"thamud","lb":[["رسول",26,143]],"ay":[[7,73,74],[11,64,65]],"s":"أُرسل إلى ثمود أصحاب الحجر، وجاءهم بالناقة آيةً، فعقروها وعتوا عن أمر ربهم، فأخذتهم الصيحة والرجفة فأصبحوا في ديارهم جاثمين.","q":{"w":"السعدي","bk":"saadi","s":7,"ay":73,"x":"أرسل الله إليهم {أخاهم صالحاً}: نبيًّا يدعوهم إلى الإيمان والتوحيد وينهاهم عن الشرك والتنديد","n":"ثمود وأخوهم صالح ودعوته.","en":"\"Allah sent to them their brother Salih as a prophet, calling them to faith and monotheism and forbidding shirk and the setting up of rivals.\""},"c":9,"sr":[[1026,1032],[1533,1540],[3072,3090],[3203,3211],[4868,4877],[6053,6057]],"ns":6},{"id":"ibrahim","n":"إبراهيم","k":6,"e":"خليل الرحمن","qw":"قومه، ومنهم أبوه والملك الذي حاجّه","ulu":1,"hd":"israel","lb":[["نبي صدّيق",19,41]],"ay":[[2,124],[6,76,79],[21,68,69]],"s":"استدلّ على قومه بالكوكب والقمر والشمس ثم تبرأ من شركهم، وحطّم أصنامهم فأُلقي في النار فجعلها الله برداً وسلاماً، ورفع القواعد من البيت مع ابنه إسماعيل، وابتُلي بالأمر بذبح ابنه ففداه الله.","q":{"w":"السعدي","bk":"saadi","s":2,"ay":124,"x":"يخبر تعالى عن عبده وخليله إبراهيم عليه السلام المتفق على إمامته وجلالته الذي كل من طوائف أهل الكتاب تدعيه، بل وكذلك المشركون أن الله ابتلاه وامتحنه بكلمات أي بأوامر ونواهٍ كما هي عادة الله في ابتلائه لعباده ليتبين الكاذب الذي لا يثبت عند الابتلاء والامتحان من الصادق، الذي ترتفع درجته، ويزيد قدره، ويزكو عمله ويخلص ذهبه، وكان من أجلِّهم في هذا المقام الخليل عليه السلام، فأتم ما ابتلاه الله به وأكمله ووفاه","n":"ابتلاء إبراهيم بالكلمات وإتمامه لها.","en":"\"Allah informs about His servant and intimate friend Ibrahim, peace be upon him, whose leadership and majesty are agreed upon, which every group of the People of the Book claims, and so do the polytheists, that Allah tried and tested him with words, that is, commands and prohibitions, as is Allah's way in testing His servants, to make clear the liar who does not stand firm under trial from the truthful, whose rank rises, whose worth increases, whose deeds are purified and whose gold is refined; and the Friend, peace be upon him, was among the foremost of them in this station, so he fulfilled what Allah tried him with, completed it and brought it to perfection.\""},"c":69,"sr":[[130,147],[264,266],[862,871],[1541,1548],[1784,1790],[2290,2299],[2533,2555],[3000,3035],[3355,3366],[3870,3900],[4698,4711],[5153,5155]],"ns":11},{"id":"lut","n":"لوط","k":7,"e":"ابن أخي إبراهيم","qw":"قومه أهل القرية المؤتفكة","ulu":0,"hd":"lut","lb":[["رسول",26,162]],"ay":[[7,80,81],[11,77,83]],"s":"آمن بإبراهيم وأُرسل إلى قوم يأتون الفاحشة، فنهاهم فلم يستجيبوا، فنجّاه الله وأهله إلا امرأته، وأمطر على قومه حجارة من سجيل.","q":{"w":"السعدي","bk":"saadi","s":7,"ay":80,"x":"إذ أرسلناه إلى قومه؛ يأمُرُهم بعبادة الله وحدَه، وينهاهم عن الفاحشة التي ما سبقَهم بها أحدٌ من العالمين","n":"نهي لوط قومه عن الفاحشة المبتدَعة.","en":"\"When We sent him to his people, commanding them to worship Allah alone and forbidding them the abomination that none among the worlds had preceded them in.\""},"c":27,"sr":[[1033,1037],[1549,1555],[1858,1878],[2556,2557],[3091,3106],[3212,3216],[3367,3374],[3920,3925],[4878,4885]],"ns":9},{"id":"ismail","n":"إسماعيل","k":8,"e":"صادق الوعد","qw":"أهله وذريته","ulu":0,"hd":"israel","lb":[["رسول نبي",19,54]],"ay":[[19,54,55],[37,101,107]],"s":"بُشّر به إبراهيم وهو حليم، وصبر لأمر الله حين رأى أبوه في المنام أنه يذبحه، وشارك أباه في رفع القواعد من البيت، ووصفه الله بصدق الوعد وأمره أهله بالصلاة والزكاة.","q":{"w":"السعدي","bk":"saadi","s":19,"ay":54,"x":"واذكر في القرآن الكريم هذا النبيَّ العظيم، الذي خَرَجَ منه الشعبُ العربيُّ، أفضل الشعوب وأجلُّها، الذين منهم سيِّد ولد آدم","n":"ثناء الله على إسماعيل وذكر ذريته.","en":"\"Remember in the noble Quran this great prophet, from whom came the Arab people, the best and most honoured of peoples, from among whom is the master of the children of Adam.\""},"c":12,"sr":[[131,135],[1786,1786],[2303,2304],[2567,2567],[3888,3894]],"ns":5},{"id":"ishaq","n":"إسحاق","k":9,"e":"نبي من الصالحين","qw":"ذريته وأهله","ulu":0,"hd":"israel","lb":[["نبي من الصالحين",37,112]],"ay":[[37,112,113],[11,71,73]],"s":"بشّرت به الملائكة إبراهيم وزوجته سارة على الكبر، ووُصف بأنه نبي من الصالحين، وجعل الله من ذريته أنبياء كثيرين.","q":{"w":"السعدي","bk":"saadi","s":37,"ay":112,"x":"هذه البشارة الثانية بإسحاقَ؛ الذي من ورائِهِ يعقوبَ، فَبُشِّرَ بوجوده وبقائه ووجود ذُرِّيَّتِهِ وكونه نبيًّا من الصالحين؛ فهي بشاراتٌ متعدِّدة","n":"البشارة بإسحاق ونبوته.","en":"\"This is the second glad tiding, of Ishaq, from whose line comes Yaqub: he was told of his existence, his survival, the existence of his offspring and his being a prophet among the righteous; so these are multiple glad tidings.\""},"c":17,"sr":[[1543,1545],[3899,3900],[4702,4704]],"ns":3},{"id":"yaqub","n":"يعقوب","k":10,"e":"إسرائيل","qw":"بنوه وهم الأسباط","ulu":0,"hd":"israel","lb":[["نبي",19,49]],"ay":[[2,132,133],[12,83,84]],"s":"وصّى بنيه بالتوحيد وهو يحتضر، وابتُلي بفقد ابنه يوسف ثم أخيه فصبر صبراً جميلاً، وابيضّت عيناه من الحزن، ثم جمع الله شمله بهما.","q":{"w":"السعدي","bk":"saadi","s":2,"ay":133,"x":"توارثت فيهم حتى وصلت ليعقوبَ فوصى بها بنيه","n":"وصية إبراهيم لبنيه ثم وصية يعقوب بالإسلام.","en":"\"... and it was handed down among them until it reached Yaqub, who charged his sons with it.\""},"c":16,"sr":[[138,139],[1599,1613],[1653,1695],[2298,2298]],"ns":3},{"id":"yusuf","n":"يوسف","k":11,"e":"الصدّيق","qw":"إخوته وأهل مصر","ulu":0,"hd":"firaun","lb":[["جاء قومه بالبينات",40,34]],"ay":[[12,4,6],[12,100,101]],"s":"رأى أحد عشر كوكباً ساجدةً له، فكاده إخوته وألقوه في الجب، ثم بيع في مصر وراودته امرأة العزيز فاستعصم، وسُجن، ثم مكّن الله له في الأرض وجمع شمله بأبويه وإخوته.","q":{"w":"السعدي","bk":"saadi","s":12,"ay":6,"x":"أي: يصطفيك ويختارك بما منَّ به عليك من الأوصاف الجليلة والمناقب الجميلة، {ويعلِّمُكَ من تأويل الأحاديث}؛ أي: من تعبير الرؤيا وبيان ما تؤول إليه الأحاديث الصادقة كالكتب السماوية ونحوها","n":"اجتباء الله ليوسف وتعليمه تأويل الأحاديث.","en":"\"That is, He will choose and select you with the lofty qualities and fine merits He has bestowed upon you, 'and teach you the interpretation of events', that is, the interpretation of dreams and what true narrations such as the heavenly scriptures and the like amount to.\""},"c":27,"sr":[[1599,1696],[4166,4166]],"ns":2},{"id":"ayyub","n":"أيوب","k":12,"e":"الصابر","qw":"لم يذكر القرآن قومه","ulu":0,"hd":"ayyub","lb":[["أُوحي إليه",4,163]],"ay":[[21,83,84],[38,41,44]],"s":"ابتُلي في جسده وأهله وماله فصبر، ونادى ربه أني مسني الضر وأنت أرحم الراحمين، فاستجاب له وكشف ضره وآتاه أهله ومثلهم معهم رحمةً منه وذكرى للعابدين.","q":{"w":"السعدي","bk":"saadi","s":21,"ay":83,"x":"واذكُر عبدَنا ورسولَنا أيوب مثنياً معظماً له رافعاً لقدرِهِ حين ابتلاه ببلاء شديدٍ فوجَدَه صابراً راضياً عنه","n":"ابتلاء أيوب وصبره.","en":"\"Remember Our servant and messenger Ayyub, praising and honouring him and raising his standing, when He tried him with severe affliction and found him patient and content with Him.\""},"c":4,"sr":[[2565,2566],[4010,4013]],"ns":2},{"id":"shuayb","n":"شعيب","k":13,"e":"خطيب الأنبياء","qw":"أهل مدين وأصحاب الأيكة","ulu":0,"hd":"madyan","lb":[["رسول",26,178]],"ay":[[11,84,85],[7,85,86]],"s":"أُرسل إلى مدين وأصحاب الأيكة يدعوهم إلى التوحيد وينهاهم عن تطفيف المكيال والميزان، فكذّبوه فأخذتهم الرجفة وعذاب يوم الظلة.","q":{"w":"السعدي","bk":"saadi","s":11,"ay":84,"x":"أرسلنا {إلى مدينَ}: القبيلة المعروفة، الذين يسكنون مَدْيَنَ، في أدنى فلسطين، {أخاهم}: في النسب، {شُعيباً}: لأنَّهم يعرفونه ويتمكَّنون من الأخذ عنه","n":"إرسال شعيب إلى مدين وإخلاص العبادة وترك التطفيف.","en":"\"We sent to Madyan, the well-known tribe, who dwell in Madyan on the edge of Palestine, their brother in lineage, Shu'ayb, because they know him and are able to take from him.\""},"c":11,"sr":[[1038,1046],[1556,1567],[3107,3122],[3375,3376]],"ns":4},{"id":"musa","n":"موسى","k":14,"e":"كليم الله","qw":"فرعون وملؤه، وبنو إسرائيل","ulu":1,"hd":"firaun","lb":[["رسول نبي",19,51]],"ay":[[20,9,14],[28,7,9],[7,143]],"s":"ألقته أمه في اليم فالتقطه آل فرعون، ثم فرّ إلى مدين، وكلّمه ربه عند الطور، وأُرسل إلى فرعون بالآيات، فأنجى الله بني إسرائيل وأغرق فرعون وجنوده، وأُنزلت عليه التوراة.","q":{"w":"السعدي","bk":"saadi","s":20,"ay":12,"x":"أخبره أنَّه ربُّه، وأمره أن يستعدَّ ويتهيَّأ لمناجاته ويهتمَّ لذلك","n":"نداء الله موسى عند الوادي المقدس.","en":"\"He told him that He is his Lord and commanded him to prepare himself for conversing with Him and to take it seriously, and to remove his sandals...\""},"c":136,"sr":[[55,80],[1056,1115],[1438,1456],[2199,2221],[2356,2445],[2941,2999],[3165,3172],[3254,3297],[4155,4178],[5726,5737]],"ns":10},{"id":"harun","n":"هارون","k":15,"e":"أخو موسى ووزيره","qw":"فرعون وبنو إسرائيل","ulu":0,"hd":"firaun","lb":[["رسول مع موسى",26,16]],"ay":[[20,29,32],[19,53]],"s":"سأل موسى ربه أن يجعل له وزيراً من أهله هارون أخاه ويشركه في أمره، فاستجاب الله له، وأرسله معه إلى فرعون، واستخلفه موسى على بني إسرائيل حين ذهب لميقات ربه.","q":{"w":"السعدي","bk":"saadi","s":20,"ay":29,"x":"أي: في النبوَّة؛ بأن تجعله نبيًّا رسولاً كما جعلتني","n":"دعاء موسى أن يكون هارون شريكه في أمره.","en":"\"... that is, in prophethood, by making him a prophet and messenger as You made me.\""},"c":20,"sr":[[1095,1095],[1103,1104],[2376,2383],[2437,2441],[2889,2890]],"ns":3},{"id":"dhulkifl","n":"ذو الكفل","k":16,"e":"من الصابرين الأخيار","qw":"لم يذكر القرآن قومه","ulu":0,"hd":null,"lb":[],"ay":[[21,85,86],[38,48]],"s":"ذكره الله مع إسماعيل وإدريس من الصابرين ومن الأخيار الذين أدخلهم في رحمته؛ ولم يفصّل القرآن في خبره، وفي نبوته خلاف بين المفسرين كما في النقل الآتي.","q":{"w":"ابن كثير","bk":"ibnkathir","s":21,"ay":85,"x":"وَأَمَّا ذُو الْكِفْلِ فَالظَّاهِرُ مِنَ السِّيَاقِ أَنَّهُ مَا قُرِنَ مَعَ الْأَنْبِيَاءِ إِلَّا وَهُوَ نَبِيٌّ. وَقَالَ آخَرُونَ: إِنَّمَا كَانَ رَجُلًا صَالِحًا، وَكَانَ مَلِكًا عَادِلًا وَحَكَمًا مُقْسِطًا، وَتَوَقَّفَ ابْنُ جَرِيرٍ فِي ذَلِكَ، فَاللَّهُ أَعْلَمُ","n":"اختلاف المفسرين في نبوة ذي الكفل.","en":"\"As for Dhul-Kifl, the apparent sense of the context is that he was not mentioned together with the prophets except that he is a prophet. Others said: he was only a righteous man, a just king and an equitable judge; and Ibn Jarir held back on it, and Allah knows best.\""},"c":2,"sr":[[2567,2568],[4017,4017]],"ns":2},{"id":"dawud","n":"داود","k":17,"e":"صاحب الزبور","qw":"بنو إسرائيل","ulu":0,"hd":"israel","lb":[["آتاه الزبور",4,163]],"ay":[[38,17,20],[34,10,11]],"s":"قتل جالوت، وآتاه الله الملك والحكمة وعلّمه مما يشاء، وسخّر معه الجبال والطير يسبّحن، وألان له الحديد ليعمل الدروع، وأُنزل عليه الزبور.","q":{"w":"السعدي","bk":"saadi","s":38,"ay":20,"x":"ومن أعظم العابدين نبيُّ الله داود عليه الصلاة والسلام، ذو {الأيۡدِ}؛ أي: القوة العظيمة على عبادةِ الله تعالى في بدنِهِ وقلبِهِ. {إنَّه أوَّابٌ}؛ أي: رجاعٌ إلى الله في جميع الأمور بالإنابة إليه بالحبِّ والتألُّه والخوف والرجا وكثرَةِ التضرُّع والدُّعاء، رجاعٌ إليه عندما يقعُ منه بعض الخلل بالإقلاع والتوبة النَّصوح","n":"عبادة داود وإنابته إلى ربه.","en":"\"Among the greatest of the worshippers is the prophet of Allah Dawud, peace be upon him, possessed of strength, that is, great strength in worshipping Allah with his body and heart. 'Indeed, he was ever turning back', returning to Allah in all matters with love, devotion, fear, hope and abundant supplication, returning to Him when some shortcoming occurs, with giving up and sincere repentance.\""},"c":16,"sr":[[257,257],[2560,2562],[3615,3616],[3986,3995]],"ns":4},{"id":"sulayman","n":"سليمان","k":18,"e":"ابن داود","qw":"بنو إسرائيل وملكة سبأ","ulu":0,"hd":"saba","lb":[["أُوحي إليه",4,163]],"ay":[[27,15,16],[38,35,38]],"s":"ورث داود، وعلّمه الله منطق الطير، وسخّر له الريح والجن والشياطين، وفهم قول النملة، وجاءه الهدهد بنبأ ملكة سبأ فدعاها إلى الله فأسلمت معه.","q":{"w":"السعدي","bk":"saadi","s":27,"ay":16,"x":"{وورث سليمانُ داودَ}؛ أي: ورث علمه ونبوَّته","n":"وراثة سليمان علم داود ونبوته.","en":"\"Sulayman inherited Dawud, that is, he inherited his knowledge and prophethood.\""},"c":17,"sr":[[2560,2564],[3173,3202],[3617,3619],[3999,4009]],"ns":4},{"id":"ilyas","n":"إلياس","k":19,"e":"من المرسلين","qw":"قوم يعبدون «بعلاً»","ulu":0,"hd":null,"lb":[["من المرسلين",37,123]],"ay":[[37,123,126],[6,85]],"s":"أُرسل إلى قوم يعبدون صنماً اسمه بعل، فأمرهم بتقوى الله وعبادته وحده، فكذّبوه؛ وأثنى الله عليه وجعل له لسان صدق في الآخرين.","q":{"w":"السعدي","bk":"saadi","s":37,"ay":123,"x":"يمدحُ تعالى عبدَه ورسولَه إلياس عليه الصلاةُ والسلام بالنبوَّةِ والرسالة والدَّعوة إلى الله، وأنَّه أمر قومَه بالتَّقوى وعبادة الله وحدَه، ونهاهم عن عبادَتِهِم صنماً لهم يُقالُ له: بعلٌ","n":"دعوة إلياس إلى ترك عبادة بعل.","en":"\"Allah praises His servant and messenger Ilyas, peace be upon him, for prophethood, messengership and calling to Allah, and that he commanded his people to piety and worship of Allah alone and forbade them from worshipping an idol of theirs called Ba'l.\""},"c":4,"sr":[[873,873],[3910,3919]],"ns":2},{"id":"yasa","n":"اليسع","k":20,"e":"من الأخيار","qw":"لم يذكر القرآن قومه","ulu":0,"hd":null,"lb":[["ممن آتاهم الله الكتاب والحكم والنبوة",6,89]],"ay":[[6,86],[38,48]],"s":"ذكره الله في عداد الأنبياء الذين فضّلهم على العالمين وفي الأخيار؛ ولم يفصّل القرآن قصته.","q":{"w":"ابن كثير","bk":"ibnkathir","s":38,"ay":48,"x":"وَقَوْلُهُ: ﴿وَاذْكُرْ إِسْمَاعِيلَ وَالْيَسَعَ وَذَا الْكِفْلِ وَكُلٌّ مِنَ الأخْيَارِ﴾ قَدْ تَقَدَّمَ الْكَلَامُ عَلَى قَصَصِهِمْ وَأَخْبَارِهِمْ مُسْتَقْصَاةً فِي سُورَةِ \"الْأَنْبِيَاءِ\" بِمَا أَغْنَى عَنْ إِعَادَتِهِ هَاهُنَا","n":"ذكر اليسع مع إسماعيل وذي الكفل.","en":"\"And His saying: 'And remember Isma'il, al-Yasa' and Dhul-Kifl, and all are among the best': the discussion of their stories and reports has already preceded in full in Surat al-Anbiya', which makes repeating it here unnecessary.\""},"c":2,"sr":[[874,874],[4017,4017]],"ns":2},{"id":"yunus","n":"يونس","k":21,"e":"ذو النون","qw":"قومه (ويذكر المفسرون أنهم أهل نينوى)","ulu":0,"hd":"yunus","lb":[["من المرسلين",37,139]],"ay":[[21,87,88],[37,139,148]],"s":"ذهب مغاضباً فالتقمه الحوت، فنادى في الظلمات أن لا إله إلا أنت سبحانك إني كنت من الظالمين، فنجّاه الله، وآمن قومه أجمعون فمتّعهم إلى حين.","q":{"w":"السعدي","bk":"saadi","s":21,"ay":87,"x":"واذكرْ عبدَنا ورسولَنا {ذَا النُّونِ}، وهو يونُس؛ أي: صاحب النون، وهي الحوت، بالذكر الجميل والثناء الحسن؛ فإنَّ الله تعالى أرسله إلى قومه، فدعاهم، فلم يؤمنوا، فوعدهم بنزول العذاب بأمدٍ سمَّاه لهم","n":"إرسال يونس إلى قومه ووعدهم بالعذاب.","en":"\"Remember Our servant and messenger Dhun-Nun, who is Yunus, that is, the one of the Nun, the whale, with fair remembrance and good praise; for Allah sent him to his people and he called them, but they did not believe, so he promised them the coming of punishment at a term he named for them.\""},"c":6,"sr":[[1461,1461],[2569,2570],[3926,3935],[5318,5320]],"ns":4},{"id":"zakariyya","n":"زكريا","k":22,"e":"كافل مريم","qw":"بنو إسرائيل","ulu":0,"hd":"israel","lb":[["ممن آتاهم الله الكتاب والحكم والنبوة",6,89]],"ay":[[19,2,6],[3,37,38]],"s":"كفل مريم وكان يجد عندها رزقاً، فنادى ربه نداءً خفياً أن يهب له وليّاً وارثاً على الكبر، فبشّره الله بيحيى وجعل له آيةً أن لا يكلّم الناس ثلاث ليال سوياً.","q":{"w":"السعدي","bk":"saadi","s":19,"ay":3,"x":"أنَّ الله تعالى اجتبى واصطفى زكريَّا عليه السلام لرسالتِهِ، وخصَّه بوحيه، فقام بذلك قيام أمثاله من المرسلين، ودعا العباد إلى ربِّه، وعلَّمهم ما علَّمه الله، ونصح لهم في حياته وبعد مماتِهِ كإخوانه من المرسلين ومن اتَّبعهم","n":"اجتباء الله لزكريا وقيامه بالرسالة.","en":"\"Allah the Exalted chose and selected Zakariyya, peace be upon him, for His message and singled him out for His revelation; he carried that out as did his like among the messengers, called the servants to their Lord, taught them what Allah had taught him, and counselled them in his life and after his death like his brothers among the messengers and those who followed them.\""},"c":7,"sr":[[329,333],[2251,2260],[2571,2572]],"ns":3},{"id":"yahya","n":"يحيى","k":23,"e":"سيد وحصور","qw":"بنو إسرائيل","ulu":0,"hd":"israel","lb":[["نبي من الصالحين",3,39]],"ay":[[19,12,15],[3,39]],"s":"وهبه الله لزكريا، وأمره أن يأخذ الكتاب بقوة وآتاه الحكم صبياً وحناناً من لدنه وزكاة، وكان براً بوالديه تقياً، وسلّم عليه يوم ولد ويوم يموت ويوم يبعث حياً.","q":{"w":"السعدي","bk":"saadi","s":19,"ay":12,"x":"أمره الله أنْ يأخذ الكتاب بقوَّة؛ أي: بجدٍّ واجتهادٍ، وذلك بالاجتهاد في حفظ ألفاظه وفهم معانيه والعمل بأوامره ونواهيه","n":"أخذ يحيى الكتاب بقوة.","en":"\"Allah commanded him to take the Book with strength, that is, with earnestness and effort, by striving to memorise its words, understand its meanings and act on its commands and prohibitions.\""},"c":5,"sr":[[331,331],[2261,2264],[2572,2572]],"ns":3},{"id":"isa","n":"عيسى","k":24,"e":"المسيح ابن مريم","qw":"بنو إسرائيل","ulu":1,"hd":"israel","lb":[["رسول",61,6],["نبي",19,30]],"ay":[[3,45,46],[19,30,33],[5,110]],"s":"وُلد من مريم بلا أب، وتكلّم في المهد، وآتاه الله الإنجيل وأيّده بروح القدس وبآيات منها إحياء الموتى بإذن الله، ونصره الحواريون، ورفعه الله إليه ولم يقتلوه ولم يصلبوه.","q":{"w":"السعدي","bk":"saadi","s":3,"ay":45,"x":"فكلامه في المهد فيه آيات وبراهين على صدقه ونبوته وبراءة أمِّه مما يظن بها من الظنون السيئة","n":"كلام عيسى في المهد آيةً على صدقه ونبوته.","en":"\"His speech in the cradle contains signs and proofs of his truthfulness and prophethood, and of his mother's innocence from the bad suspicions held about her.\""},"c":36,"sr":[[334,355],[648,651],[778,786],[2265,2285],[4381,4389],[5168,5168],[5176,5176]],"ns":6},{"id":"muhammad","n":"محمد ﷺ","k":25,"e":"خاتم النبيين","qw":"الناس كافة","ulu":1,"hd":null,"lb":[["رسول الله وخاتم النبيين",33,40]],"ay":[[33,40],[34,28],[48,29]],"s":"أُرسل رحمةً للعالمين وأُنزل عليه القرآن، وخاطبه الله بالنبوة والرسالة، وخُتمت به النبوات؛ ورسالته إلى الناس كافة.","q":{"w":"السعدي","bk":"saadi","s":33,"ay":40,"x":"أي: هذه مرتبته؛ مرتبةُ المطاع المتبوع المهتدَى به الْمُؤْمَنِ له الذي يجبُ تقديم محبته على محبة كلِّ أحدٍ","n":"مرتبة النبي ﷺ ورسالته.","en":"\"That is, this is his rank: the rank of the one obeyed, followed, guided by, believed in, whose love must come before the love of anyone else.\""},"c":5,"sr":[[436,436],[3572,3572],[4546,4546],[4611,4611],[5168,5168]],"ns":5}],"ch":[{"id":"nabirasul","t":"النبي والرسول","d":"يذكر القرآن «النبي» و«الرسول»، ومن الأنبياء من وصفه الله بالوصفين معاً كموسى وإسماعيل عليهما السلام. وللعلماء في التفريق بينهما أقوال، منها ما أثبته المفسرون في كتبهم بلفظه أدناه، ومنها أن كل رسول نبي وليس كل نبي رسولاً.","ay":[{"t":"ما أرسل الله من رسول ولا نبي","r":[22,52],"n":"عطف الله «النبي» على «الرسول» في الآية، فدل على أن لكل منهما معنى، وشرحها الجلالان بأن الرسول أُمر بالتبليغ والنبي لم يُؤمر به."},{"t":"موسى رسول نبي","r":[19,51],"n":"وصف الله موسى بالرسالة والنبوة معاً، وبيّن السعدي في تفسيرها الفرق بين الوصفين."},{"t":"إسماعيل رسول نبي","r":[19,54,55],"n":"ووصف الله إسماعيل كذلك بالرسالة والنبوة وبصدق الوعد."}]},{"id":"named","t":"الأنبياء المذكورون بأسمائهم","d":"خمسة وعشرون نبياً ورسولاً سمّاهم القرآن بأسمائهم، مرتّبين بحسب ما ذكره المؤرخون والمفسرون من التقدّم الزمني. لكل نبي: ملخص ما صرّح به القرآن، وقومه، ووصف القرآن له، وآيات مختارة بخط المصحف، ونقل من تفسير بلفظه، وما صحّ من الحديث فيه إن وُجد.","ay":[]},{"id":"ulu","t":"أولو العزم من الرسل","d":"أمر الله نبيه ﷺ أن يصبر كما صبر أولو العزم من الرسل، وسمّى في موضعين خمسة من الرسل. وللمفسرين في عدّهم أقوال، أشهرها: نوح وإبراهيم وموسى وعيسى ومحمد عليهم الصلاة والسلام.","ay":[{"t":"فاصبر كما صبر أولو العزم","r":[46,35],"n":"الأمر بالصبر اقتداءً بأولي العزم."},{"t":"ميثاق النبيين","r":[33,7],"n":"أخذ الله الميثاق من النبيين ومنهم خمسة سمّاهم: نوح وإبراهيم وموسى وعيسى، ومحمد ﷺ."},{"t":"ما وصّى به نوحاً وإبراهيم وموسى وعيسى","r":[42,13],"n":"شرع لنا من الدين ما وصّى به نوحاً والذي أوحاه إلى محمد وما وصّى به إبراهيم وموسى وعيسى: أن أقيموا الدين ولا تتفرقوا فيه."}]},{"id":"amma","t":"لكل أمة رسول","d":"قرّر القرآن أن الله بعث في كل أمة رسولاً بلسان قومه، وأن منهم من قصّ الله خبره ومنهم من لم يقصصه؛ فالمسمّون في القرآن بعض الرسل لا كلّهم.","ay":[{"t":"في كل أمة رسول","r":[16,36],"n":"دعوة الرسل واحدة: أن اعبدوا الله واجتنبوا الطاغوت."},{"t":"ما من أمة إلا خلا فيها نذير","r":[35,24],"n":"ما من أمة إلا مضى فيها نذير."},{"t":"ولكل أمة رسول","r":[10,47],"n":"فإذا جاء رسولهم قُضي بينهم بالقسط."},{"t":"بلسان قومه","r":[14,4],"n":"أُرسل كل رسول بلسان قومه ليبيّن لهم."}]},{"id":"unnamed","t":"من ذُكروا من غير تسمية","d":"ذكر القرآن رسلاً وأنبياء بلا أسماء: رسلاً لم يقصصهم، وثلاثة رسل أُرسلوا إلى أصحاب القرية، ونبياً من بني إسرائيل طلبوا منه ملكاً. ويوسم هنا كل ما ليس باسم صريح، ولا يُجزم بتعيين من لم يعيّنه النص إلا بما نقله المفسرون منسوباً إلى قائله.","ay":[{"t":"رسل لم يقصصهم الله","r":[4,164],"n":"فيهم من قصّ الله خبره على نبيه ومنهم من لم يقصص، وهذا يدل على كثرتهم."},{"t":"ولقد أرسلنا رسلاً من قبلك","r":[40,78],"n":"منهم من قصّ الله عليك ومنهم من لم يقصص."},{"t":"رسل القرية","r":[36,13,14],"n":"أُرسل إلى أصحاب القرية اثنان فكذّبوهما فعزّز الله بثالث؛ ولم يسمّهم القرآن ولا سمّى القرية."},{"t":"نبي بني إسرائيل وطالوت","r":[2,246,247],"n":"طلب بنو إسرائيل من نبيهم ملكاً، ولم يُسمَّ النبي في الآية."},{"t":"الذي مرّ على قرية","r":[2,259],"n":"رجل مرّ على قرية خاوية فأماته الله مئة عام ثم بعثه؛ لم يُسمَّ ولم يُنصّ على نبوته في الآية، واختلف المفسرون في تعيينه."}]},{"id":"khilaf","t":"من اختُلف في نبوتهم","d":"شخصيات ذكرها القرآن اختلف العلماء في نبوتها، وليست من الخمسة والعشرين المنصوص عليهم بأسمائهم؛ فنعرض الآيات وقول المفسر بلفظه دون ترجيح من عندنا.","ay":[{"t":"العبد الصالح (الخضر)","r":[18,65],"n":"عبد من عباد الله آتاه الله رحمة وعلماً من لدنه."},{"t":"ذو القرنين","r":[18,83,84],"n":"مكّن الله له في الأرض وآتاه من كل شيء سبباً."},{"t":"لقمان","r":[31,12],"n":"آتاه الله الحكمة وأمره بالشكر."}]},{"id":"khatam","t":"خاتم النبيين","d":"ختم الله النبوة بمحمد ﷺ، وأرسله إلى الناس كافة، وبشّر به عيسى عليه السلام باسم أحمد؛ وفي الأحاديث الصحيحة تمثيل النبوة ببناء لم يبق منه إلا موضع لبنة.","ay":[{"t":"ولكن رسول الله وخاتم النبيين","r":[33,40],"n":"ختام النبوات بمحمد ﷺ."},{"t":"وما أرسلناك إلا كافة للناس","r":[34,28],"n":"عموم رسالته ﷺ."},{"t":"ومبشراً برسول يأتي من بعدي اسمه أحمد","r":[61,6],"n":"بشارة عيسى بالنبي ﷺ."}]},{"id":"sunna","t":"من أحاديث الأنبياء","d":"أحاديث صحيحة في صحيح البخاري عن الأنبياء وسيرهم وفضلهم وأدبهم معهم، مقتطعة بلفظها من الكتاب المضمّن بترقيمها.","ay":[]}],"h":[{"id":"ikhwa","t":"الأنبياء إخوة لعلّات","x":"أَنَا أَوْلَى النَّاسِ بِعِيسَى ابْنِ مَرْيَمَ فِي الدُّنْيَا وَالآخِرَةِ، وَالأَنْبِيَاءُ إِخْوَةٌ لِعَلاَّتٍ، أُمَّهَاتُهُمْ شَتَّى، وَدِينُهُمْ وَاحِدٌ","src":[["bukhari","3443"]],"gr":"صحيح: رواه البخاري","dg":"","f":"دين الأنبياء واحد في أصله وهو التوحيد، وإن اختلفت شرائعهم؛ كالإخوة لأب واحد وأمهات مختلفة.","en":"The Prophet ﷺ said: \"I am the closest of people to Isa son of Maryam in this world and the next, and the prophets are brothers from different mothers; their religion is one.\"","ch":"nabirasul","p":"isa"},{"id":"khatamb","t":"مثل النبوة كبناء إلا لبنة","x":"إِنَّ مَثَلِي وَمَثَلَ الأَنْبِيَاءِ مِنْ قَبْلِي كَمَثَلِ رَجُلٍ بَنَى بَيْتًا فَأَحْسَنَهُ وَأَجْمَلَهُ، إِلاَّ مَوْضِعَ لَبِنَةٍ مِنْ زَاوِيَةٍ، فَجَعَلَ النَّاسُ يَطُوفُونَ بِهِ وَيَعْجَبُونَ لَهُ، وَيَقُولُونَ هَلاَّ وُضِعَتْ هَذِهِ اللَّبِنَةُ قَالَ فَأَنَا اللَّبِنَةُ، وَأَنَا خَاتِمُ النَّبِيِّينَ","src":[["bukhari","3535"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تمثيل لاكتمال بناء النبوات بمحمد ﷺ؛ فهو اللبنة التي تمّ بها البناء.","en":"The Prophet ﷺ said: \"My likeness and the likeness of the prophets before me is that of a man who built a house and made it beautiful and fine, except for the place of one brick in a corner. People went around it marvelling and saying: if only this brick were put in! He said: I am that brick, and I am the Seal of the Prophets.\"","ch":"khatam","p":"muhammad"},{"id":"lanabi","t":"لا نبي بعدي","x":"كَانَتْ بَنُو إِسْرَائِيلَ تَسُوسُهُمُ الأَنْبِيَاءُ، كُلَّمَا هَلَكَ نَبِيٌّ خَلَفَهُ نَبِيٌّ، وَإِنَّهُ لاَ نَبِيَّ بَعْدِي","src":[["bukhari","3455"]],"gr":"صحيح: رواه البخاري","dg":"","f":"كان بنو إسرائيل يُقاد أمرهم بالأنبياء كلما مات نبي خلفه نبي، أما هذه الأمة فلا نبي بعد نبيها.","en":"The Prophet ﷺ said: \"The Children of Israel were led by prophets: whenever a prophet died another prophet succeeded him, and there is no prophet after me.\"","ch":"khatam","p":"muhammad"},{"id":"ayat","t":"الآيات والوحي","x":"مَا مِنَ الأَنْبِيَاءِ نَبِيٌّ إِلاَّ أُعْطِيَ مَا مِثْلُهُ آمَنَ عَلَيْهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَىَّ فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ","src":[["bukhari","4981"]],"gr":"صحيح: رواه البخاري","dg":"","f":"أعظم ما أُوتيه النبي ﷺ وحي يُتلى باقٍ إلى يوم القيامة؛ فهو أكثر الأنبياء أتباعاً.","en":"The Prophet ﷺ said: \"Every prophet was given what the like of which people believe in, and what I was given is a revelation that Allah revealed to me, so I hope to have the most followers among them on the Day of Resurrection.\"","ch":"khatam","p":"muhammad"},{"id":"ra3","t":"ما بعث الله نبياً إلا رعى الغنم","x":"\" مَا بَعَثَ اللَّهُ نَبِيًّا إِلاَّ رَعَى الْغَنَمَ \". فَقَالَ أَصْحَابُهُ وَأَنْتَ فَقَالَ \" نَعَمْ كُنْتُ أَرْعَاهَا عَلَى قَرَارِيطَ لأَهْلِ مَكَّةَ\"","src":[["bukhari","2262"]],"gr":"صحيح: رواه البخاري","dg":"","f":"الرعي تهذيب للنفس بالصبر والرفق قبل رعاية الناس؛ وكان النبي ﷺ يرعى الغنم كغيره.","en":"The Prophet ﷺ said: \"Allah did not send a prophet except that he tended sheep.\" His companions said: And you? He said: \"Yes, I used to tend them for the people of Makkah for a few qirats.\"","ch":"sunna","p":"muhammad"},{"id":"ibrahimh","t":"ولكن ليطمئن قلبي","x":"نَحْنُ أَحَقُّ بِالشَّكِّ مِنْ إِبْرَاهِيمَ إِذْ قَالَ {رَبِّ أَرِنِي كَيْفَ تُحْيِي الْمَوْتَى قَالَ أَوَلَمْ تُؤْمِنْ قَالَ بَلَى وَلَكِنْ لِيَطْمَئِنَّ قَلْبِي}","src":[["bukhari","4537"]],"gr":"صحيح: رواه البخاري","dg":"","f":"سؤال إبراهيم عليه السلام لم يكن شكّاً بل طلباً لزيادة الطمأنينة بمشاهدة ما آمن به.","en":"The Prophet ﷺ said: \"We are more deserving of doubt than Ibrahim when he said: My Lord, show me how You give life to the dead. He said: Do you not believe? He said: Yes, but to put my heart at rest.\"","ch":"named","p":"ibrahim"},{"id":"lutyusuf","t":"يرحم الله لوطاً","x":"وَيَرْحَمُ اللَّهُ لُوطًا، لَقَدْ كَانَ يَأْوِي إِلَى رُكْنٍ شَدِيدٍ وَلَوْ لَبِثْتُ فِي السِّجْنِ طُولَ مَا لَبِثَ يُوسُفُ لأَجَبْتُ الدَّاعِيَ","src":[["bukhari","3372"]],"gr":"صحيح: رواه البخاري","dg":"","f":"ثناء على صبر يوسف عليه السلام في السجن وتمنٍّ لما كان لوط عليه السلام يتمناه من الركن الشديد.","en":"The Prophet ﷺ said: \"May Allah have mercy on Lut, for he used to take refuge in a strong pillar; and had I stayed in prison as long as Yusuf stayed, I would have answered the summoner.\"","ch":"named","p":"lut"},{"id":"karim","t":"الكريم ابن الكريم","x":"الْكَرِيمُ بْنُ الْكَرِيمِ بْنِ الْكَرِيمِ بْنِ الْكَرِيمِ يُوسُفُ بْنُ يَعْقُوبَ بْنِ إِسْحَاقَ بْنِ إِبْرَاهِيمَ","src":[["bukhari","4688"]],"gr":"صحيح: رواه البخاري","dg":"","f":"يوسف عليه السلام هو الرابع في سلسلة الكرم والنبوة: يوسف بن يعقوب بن إسحاق بن إبراهيم.","en":"The Prophet ﷺ said: \"The noble son of the noble son of the noble son of the noble: Yusuf son of Yaqub son of Ishaq son of Ibrahim.\"","ch":"named","p":"yusuf"},{"id":"dawudkasb","t":"يأكل من عمل يده","x":"أَنَّ دَاوُدَ ـ عَلَيْهِ السَّلاَمُ ـ كَانَ لاَ يَأْكُلُ إِلاَّ مِنْ عَمَلِ يَدِهِ","src":[["bukhari","2073"]],"gr":"صحيح: رواه البخاري","dg":"","f":"مع ما آتاه الله من الملك كان داود عليه السلام يأكل من كسب يده، وفي ذلك فضل العمل باليد.","en":"The Prophet ﷺ said that the prophet of Allah Dawud, peace be upon him, used to eat only from the work of his own hand.","ch":"named","p":"dawud"},{"id":"dawudquran","t":"خُفّف على داود القرآن","x":"خُفِّفَ عَلَى دَاوُدَ ـ عَلَيْهِ السَّلاَمُ ـ الْقُرْآنُ، فَكَانَ يَأْمُرُ بِدَوَابِّهِ فَتُسْرَجُ، فَيَقْرَأُ الْقُرْآنَ قَبْلَ أَنْ تُسْرَجَ دَوَابُّهُ، وَلاَ يَأْكُلُ إِلاَّ مِنْ عَمَلِ يَدِهِ","src":[["bukhari","3417"]],"gr":"صحيح: رواه البخاري","dg":"","f":"والمراد بالقرآن هنا الزبور، وكان يقرؤه في زمن يسير ثم يأكل من عمل يده.","en":"The Prophet ﷺ said: \"The recitation was made light for Dawud, peace be upon him; he would order his mounts to be saddled and would recite the Quran before they were saddled, and he ate only from the work of his hand.\"","ch":"named","p":"dawud"},{"id":"naml","t":"نبي نزل تحت شجرة فلدغته نملة","x":"نَزَلَ نَبِيٌّ مِنَ الأَنْبِيَاءِ تَحْتَ شَجَرَةٍ فَلَدَغَتْهُ نَمْلَةٌ، فَأَمَرَ بِجَهَازِهِ فَأُخْرِجَ مِنْ تَحْتِهَا، ثُمَّ أَمَرَ بِبَيْتِهَا فَأُحْرِقَ بِالنَّارِ، فَأَوْحَى اللَّهُ إِلَيْهِ فَهَلاَّ نَمْلَةً وَاحِدَةً","src":[["bukhari","3319"]],"gr":"صحيح: رواه البخاري","dg":"","f":"عتاب لنبي على أن عاقب أمة بسبب أذى واحدة منها؛ والحديث لم يُسمِّ ذلك النبي.","en":"The Prophet ﷺ said: \"A prophet among the prophets stopped under a tree and an ant bit him; he ordered his gear removed from under it and its dwelling burned. So Allah revealed to him: Could it not have been a single ant?\" The hadith does not name that prophet.","ch":"sunna","p":null},{"id":"ayyubh","t":"جراد من ذهب","x":"بَيْنَمَا أَيُّوبُ يَغْتَسِلُ عُرْيَانًا خَرَّ عَلَيْهِ رِجْلُ جَرَادٍ مِنْ ذَهَبٍ، فَجَعَلَ يَحْثِي فِي ثَوْبِهِ، فَنَادَى رَبُّهُ يَا أَيُّوبُ، أَلَمْ أَكُنْ أَغْنَيْتُكَ عَمَّا تَرَى قَالَ بَلَى يَا رَبِّ، وَلَكِنْ لاَ غِنَى لِي عَنْ بَرَكَتِكَ","src":[["bukhari","3391"]],"gr":"صحيح: رواه البخاري","dg":"","f":"حرص أيوب عليه السلام على بركة الله وفضله، وأن العبد لا يستغني عنها وإن كثر ماله.","en":"The Prophet ﷺ said: \"While Ayyub was bathing naked, a swarm of golden locusts fell on him and he began to scoop them into his garment. His Lord called him: Ayyub, have I not made you free of need of what you see? He said: Yes, my Lord, but I am not free of need of Your blessing.\"","ch":"named","p":"ayyub"},{"id":"yunush","t":"لا تفضّلوني على يونس","x":"لاَ يَنْبَغِي لِعَبْدٍ أَنْ يَقُولَ أَنَا خَيْرٌ مِنْ يُونُسَ بْنِ مَتَّى","src":[["bukhari","3395"]],"gr":"صحيح: رواه البخاري","dg":"","f":"نهي عن الاستعلاء على نبي من الأنبياء؛ فكلهم أُوتوا الفضل.","en":"The Prophet ﷺ said: \"It is not fitting for a servant to say: I am better than Yunus son of Matta.\"","ch":"named","p":"yunus"},{"id":"musah","t":"رحمة الله على موسى","x":"رَحْمَةُ اللَّهِ عَلَى مُوسَى، لَقَدْ أُوذِيَ بِأَكْثَرَ مِنْ هَذَا فَصَبَرَ","src":[["bukhari","4335"]],"gr":"صحيح: رواه البخاري","dg":"","f":"تسلية للنبي ﷺ بصبر موسى عليه السلام على أذى قومه.","en":"The Prophet ﷺ said: \"May Allah have mercy on Musa; he was hurt with more than this and he was patient.\"","ch":"named","p":"musa"},{"id":"adamh","t":"خلق الله آدم وطوله ستون ذراعاً","x":"خَلَقَ اللَّهُ آدَمَ وَطُولُهُ سِتُّونَ ذِرَاعًا، ثُمَّ قَالَ اذْهَبْ فَسَلِّمْ عَلَى أُولَئِكَ مِنَ الْمَلاَئِكَةِ، فَاسْتَمِعْ مَا يُحَيُّونَكَ، تَحِيَّتُكَ وَتَحِيَّةُ ذُرِّيَّتِكَ. فَقَالَ السَّلاَمُ عَلَيْكُمْ. فَقَالُوا السَّلاَمُ عَلَيْكَ وَرَحْمَةُ اللَّهِ. فَزَادُوهُ وَرَحْمَةُ اللَّهِ. فَكُلُّ مَنْ يَدْخُلُ الْجَنَّةَ عَلَى صُورَةِ آدَمَ، فَلَمْ يَزَلِ الْخَلْقُ يَنْقُصُ حَتَّى الآنَ","src":[["bukhari","3326"]],"gr":"صحيح: رواه البخاري","dg":"","f":"أول تحية بين آدم والملائكة هي «السلام عليكم»، وسنّ للذرية بعده.","en":"The Prophet ﷺ said: \"Allah created Adam sixty cubits tall, then said: go and greet that group of angels and listen to how they greet you, for it is your greeting and the greeting of your descendants. He said: Peace be upon you. They said: Peace be upon you and the mercy of Allah, adding 'and the mercy of Allah'. So everyone who enters Paradise will be in the form of Adam; creation has been shrinking ever since.\"","ch":"named","p":"adam"},{"id":"maryam","t":"إلا مريم وابنها","x":"مَا مِنْ مَوْلُودٍ يُولَدُ إِلاَّ وَالشَّيْطَانُ يَمَسُّهُ حِينَ يُولَدُ، فَيَسْتَهِلُّ صَارِخًا مِنْ مَسِّ الشَّيْطَانِ إِيَّاهُ، إِلاَّ مَرْيَمَ وَابْنَهَا","src":[["bukhari","4548"]],"gr":"صحيح: رواه البخاري","dg":"","f":"عصمة مريم وابنها عيسى عليهما السلام من مسّ الشيطان عند الولادة، استجابةً لدعاء أم مريم.","en":"The Prophet ﷺ said: \"There is no child born but that Satan touches him when he is born, so he cries out from Satan's touch, except Maryam and her son.\"","ch":"named","p":"isa"}],"q":[{"ch":"nabirasul","w":"الجلالان","bk":"jalalayn","s":22,"ay":52,"x":"﴿وما أرْسَلْنا مِن قَبْلك مِن رَسُول﴾ هُوَ نَبِيّ أُمِرَ بِالتَّبْلِيغِ ﴿ولا نَبِيّ﴾ أيْ لَمْ يُؤْمَر بِالتَّبْلِيغِ","n":"تعريف الرسول والنبي عند صاحبي الجلالين.","en":"\"'We did not send before you any messenger': he is a prophet commanded to convey, 'nor prophet': that is, one not commanded to convey.\""},{"ch":"nabirasul","w":"السعدي","bk":"saadi","s":19,"ay":51,"x":"جمع الله له بين الرسالة والنبوَّة؛ فالرسالة تقتضي تبليغ كلام المرسِل وتبليغَ جميع ما جاء به من الشرع دقِّه وجِلِّه، والنبوَّة تقتضي إيحاءَ الله إليه وتخصيصه بإنزال الوَحْي إليه؛ فالنبوَّة بينه وبين ربِّه، والرسالة بينَه وبين الخَلْق","n":"الفرق بين الوصفين عند السعدي.","en":"\"Allah combined for him messengership and prophethood: messengership requires conveying the speech of the Sender and everything He brought of the law, small and great, while prophethood requires Allah's revealing to him and singling him out with the sending down of revelation; so prophethood is between him and his Lord, and messengership is between him and creation.\""},{"ch":"ulu","w":"ابن كثير","bk":"ibnkathir","s":46,"ay":35,"x":"وَقَدِ اخْتَلَفُوا فِي تَعْدَادِ أُولِي الْعَزْمِ عَلَى أَقْوَالٍ، وَأَشْهَرُهَا أَنَّهُمْ: نُوحٌ، وَإِبْرَاهِيمُ، وَمُوسَى، وَعِيسَى، وَخَاتَمُ الْأَنْبِيَاءِ كُلِّهِمْ مُحَمَّدٌ ﷺ، قَدْ نَصَّ اللَّهُ عَلَى أَسْمَائِهِمْ مِنْ بَيْنِ الْأَنْبِيَاءِ فِي آيَتَيْنِ مِنْ سُورَتَي \"الْأَحْزَابِ\" وَ \"الشُّورَى\"","n":"أشهر الأقوال في عدّ أولي العزم.","en":"\"They differed on counting the messengers of firm resolve in several views, and the best known is that they are Nuh, Ibrahim, Musa, Isa and the Seal of all prophets Muhammad ﷺ; Allah named them among the prophets in two verses, in Surat al-Ahzab and Surat al-Shura.\""},{"ch":"ulu","w":"الميسر","bk":"muyassar","s":46,"ay":35,"x":"وهم على المشهور: نوح وإبراهيم وموسى وعيسى وأنت منهم","n":"العدّ المشهور في التفسير الميسر.","en":"\"... as the messengers of firm resolve before you were patient, who are, on the well-known view, Nuh, Ibrahim, Musa and Isa, and you are among them.\""},{"ch":"ulu","w":"القرطبي","bk":"qurtubi","s":46,"ay":35,"x":"قَالَ مُجَاهِدٌ: هُمْ خَمْسَةٌ: نُوحٌ، وَإِبْرَاهِيمُ، وَمُوسَى، وَعِيسَى، وَمُحَمَّدٌ عَلَيْهِمُ الصَّلَاةُ وَالسَّلَامُ. وَهُمْ أَصْحَابُ الشَّرَائِعِ","n":"قول مجاهد في أولي العزم.","en":"\"Mujahid said: they are five: Nuh, Ibrahim, Musa, Isa and Muhammad, blessings and peace be upon them, and they are the bearers of the laws.\""},{"ch":"ulu","w":"البغوي","bk":"baghawi","s":46,"ay":35,"x":"فَقَالَ ابْنُ زَيْدٍ: كُلُّ الرُّسُلِ كَانُوا أُولِي عَزْمٍ، لَمْ يَبْعَثِ اللَّهُ نَبِيًّا إِلَّا كَانَ ذَا عَزْمٍ وَحَزْمٍ، وَرَأْيٍ وَكَمَالِ عَقْلٍ","n":"قول يرى أن الرسل كلهم أولو عزم.","en":"\"Ibn Zayd said: all the messengers were of firm resolve; Allah never sent a prophet except one with resolve, firmness, sound judgement and perfect intellect.\""},{"ch":"amma","w":"السعدي","bk":"saadi","s":16,"ay":36,"x":"يخبر تعالى أن حجَّته قامت على جميع الأمم، وأنَّه ما من أمَّة متقدِّمة أو متأخِّرة إلاَّ وبعث الله فيها رسولاً، وكلُّهم متَّفقون على دعوةٍ واحدةٍ ودينٍ واحدٍ","n":"قيام الحجة بالرسل على كل الأمم ووحدة دعوتهم.","en":"\"Allah informs that His proof has been established against all nations, and that there is no nation, earlier or later, except that Allah sent among it a messenger, and all of them agree on one call and one religion.\""},{"ch":"unnamed","w":"السعدي","bk":"saadi","s":4,"ay":164,"x":"وذكر أن الرُّسل منهم من قصَّه الله على رسوله، ومنهم من لم يَقْصُصْه عليه، وهذا يدلُّ على كثرتِهِم","n":"كثرة الرسل ومن لم يُقصّ خبره.","en":"\"He mentioned that among the messengers are those He recounted to His Messenger and those He did not recount, and this shows how many they are.\""},{"ch":"unnamed","w":"السعدي","bk":"saadi","s":36,"ay":13,"x":"وتعيينُ تلك القريةِ لو كان فيه فائدةٌ؛ لعيَّنَها الله","n":"لماذا لم يسمّ القرآن القرية.","en":"\"And identifying that town, had there been any benefit in it, Allah would have identified it.\""},{"ch":"unnamed","w":"السعدي","bk":"saadi","s":36,"ay":14,"x":"أي: قوَّيْناهما بثالثٍ، فصاروا ثلاثةَ رسل؛ اعتناءً من الله بهم، وإقامةً للحجَّة بتوالي الرسل إليهم","n":"تعزيز الرسولين بثالث.","en":"\"That is, We strengthened them with a third, so they became three messengers, out of care from Allah for them and to establish the proof by the succession of messengers to them.\""},{"ch":"unnamed","w":"السعدي","bk":"saadi","s":2,"ay":246,"x":"أن يطلبوا من نبيهم أن يعين لهم ملكاً لينقطع النزاع بتعيينه وتحصلَ الطاعة التامة","n":"طلبهم من نبيهم تعيين ملك، والنبي هنا غير مسمّى في الآية.","en":"\"... that they ask their prophet to appoint a king for them so that dispute ceases through his appointment and complete obedience is achieved.\""},{"ch":"unnamed","w":"ابن كثير","bk":"ibnkathir","s":2,"ay":259,"x":"وَحَكَاهُ ابْنُ جَرِيرٍ وَابْنُ أَبِي حَاتِمٍ عَنِ ابْنِ عَبَّاسٍ وَالْحَسَنِ وَقَتَادَةَ وَالسُّدِّيِّ وَسُلَيْمَانَ بْنِ بُرَيْدَة وَهَذَا الْقَوْلُ هُوَ الْمَشْهُورُ. وَقَالَ وَهْبُ بْنُ مُنَبِّهٍ وَعَبْدُ اللَّهِ بْنُ عُبَيْدِ بْنِ عُمَيْرٍ: هُوَ أَرْمِيَا بْنُ حَلْقِيَا","n":"اختلاف تعيين الذي مرّ على القرية.","en":"\"Ibn Jarir and Ibn Abi Hatim related it from Ibn 'Abbas, al-Hasan, Qatadah, al-Suddi and Sulayman ibn Buraydah, and this is the well-known view. Wahb ibn Munabbih and 'Abdullah ibn 'Ubayd ibn 'Umayr said: he is Armiya son of Hilqiya.\""},{"ch":"khilaf","w":"السعدي","bk":"saadi","s":18,"ay":65,"x":"وهو الخضر، وكان عبداً صالحاً لا نبيًّا على الصحيح","n":"قول السعدي في العبد الصالح.","en":"\"... he is al-Khidr, and he was a righteous servant, not a prophet, on the sound view.\""},{"ch":"khilaf","w":"السعدي","bk":"saadi","s":18,"ay":83,"x":"أي: مَلَّكَهُ الله تعالى ومكَّنه من النفوذ في أقطار الأرض وانقيادهم له","n":"تمكين ذي القرنين في الأرض.","en":"\"That is, Allah the Exalted gave him dominion and empowered him to reach the ends of the earth, with its people submitting to him.\""},{"ch":"khilaf","w":"السعدي","bk":"saadi","s":31,"ay":12,"x":"يخبرُ تعالى عن امتنانِهِ على عبدِهِ الفاضل لقمان بالحكمة، وهي العلم بالحقِّ على وجهه وحكمته","n":"وصف لقمان بالحكمة.","en":"\"Allah informs of His favour upon His excellent servant Luqman with wisdom, which is knowledge of the truth as it is and in its wisdom.\""},{"ch":"khatam","w":"السعدي","bk":"saadi","s":33,"ay":40,"x":"أي: هذه مرتبته؛ مرتبةُ المطاع المتبوع المهتدَى به الْمُؤْمَنِ له الذي يجبُ تقديم محبته على محبة كلِّ أحدٍ","n":"مرتبة الخاتم ﷺ.","en":"\"That is, this is his rank: the rank of the one obeyed and followed, guided by, believed in, whose love must come before the love of anyone else.\""}],"ay":{"36":"وَإِذۡ قَالَ رَبُّكَ لِلۡمَلَٰٓئِكَةِ إِنِّي جَاعِلٞ فِي ٱلۡأَرۡضِ خَلِيفَةٗۖ قَالُوٓاْ أَتَجۡعَلُ فِيهَا مَن يُفۡسِدُ فِيهَا وَيَسۡفِكُ ٱلدِّمَآءَ وَنَحۡنُ نُسَبِّحُ بِحَمۡدِكَ وَنُقَدِّسُ لَكَۖ قَالَ إِنِّيٓ أَعۡلَمُ مَا لَا تَعۡلَمُونَ","37":"وَعَلَّمَ ءَادَمَ ٱلۡأَسۡمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمۡ عَلَى ٱلۡمَلَٰٓئِكَةِ فَقَالَ أَنۢبِـُٔونِي بِأَسۡمَآءِ هَٰٓؤُلَآءِ إِن كُنتُمۡ صَٰدِقِينَ","130":"۞ وَإِذِ ٱبۡتَلَىٰٓ إِبۡرَٰهِـۧمَ رَبُّهُۥ بِكَلِمَٰتٖ فَأَتَمَّهُنَّۖ قَالَ إِنِّي جَاعِلُكَ لِلنَّاسِ إِمَامٗاۖ قَالَ وَمِن ذُرِّيَّتِيۖ قَالَ لَا يَنَالُ عَهۡدِي ٱلظَّٰلِمِينَ","138":"وَوَصَّىٰ بِهَآ إِبۡرَٰهِـۧمُ بَنِيهِ وَيَعۡقُوبُ يَٰبَنِيَّ إِنَّ ٱللَّهَ ٱصۡطَفَىٰ لَكُمُ ٱلدِّينَ فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسۡلِمُونَ","139":"أَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ حَضَرَ يَعۡقُوبَ ٱلۡمَوۡتُ إِذۡ قَالَ لِبَنِيهِ مَا تَعۡبُدُونَ مِنۢ بَعۡدِيۖ قَالُواْ نَعۡبُدُ إِلَٰهَكَ وَإِلَٰهَ ءَابَآئِكَ إِبۡرَٰهِـۧمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ إِلَٰهٗا وَٰحِدٗا وَنَحۡنُ لَهُۥ مُسۡلِمُونَ","252":"أَلَمۡ تَرَ إِلَى ٱلۡمَلَإِ مِنۢ بَنِيٓ إِسۡرَٰٓءِيلَ مِنۢ بَعۡدِ مُوسَىٰٓ إِذۡ قَالُواْ لِنَبِيّٖ لَّهُمُ ٱبۡعَثۡ لَنَا مَلِكٗا نُّقَٰتِلۡ فِي سَبِيلِ ٱللَّهِۖ قَالَ هَلۡ عَسَيۡتُمۡ إِن كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ أَلَّا تُقَٰتِلُواْۖ قَالُواْ وَمَا لَنَآ أَلَّا نُقَٰتِلَ فِي سَبِيلِ ٱللَّهِ وَقَدۡ أُخۡرِجۡنَا مِن دِيَٰرِنَا وَأَبۡنَآئِنَاۖ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ تَوَلَّوۡاْ إِلَّا قَلِيلٗا مِّنۡهُمۡۚ وَٱللَّهُ عَلِيمُۢ بِٱلظَّٰلِمِينَ","253":"وَقَالَ لَهُمۡ نَبِيُّهُمۡ إِنَّ ٱللَّهَ قَدۡ بَعَثَ لَكُمۡ طَالُوتَ مَلِكٗاۚ قَالُوٓاْ أَنَّىٰ يَكُونُ لَهُ ٱلۡمُلۡكُ عَلَيۡنَا وَنَحۡنُ أَحَقُّ بِٱلۡمُلۡكِ مِنۡهُ وَلَمۡ يُؤۡتَ سَعَةٗ مِّنَ ٱلۡمَالِۚ قَالَ إِنَّ ٱللَّهَ ٱصۡطَفَىٰهُ عَلَيۡكُمۡ وَزَادَهُۥ بَسۡطَةٗ فِي ٱلۡعِلۡمِ وَٱلۡجِسۡمِۖ وَٱللَّهُ يُؤۡتِي مُلۡكَهُۥ مَن يَشَآءُۚ وَٱللَّهُ وَٰسِعٌ عَلِيمٞ","265":"أَوۡ كَٱلَّذِي مَرَّ عَلَىٰ قَرۡيَةٖ وَهِيَ خَاوِيَةٌ عَلَىٰ عُرُوشِهَا قَالَ أَنَّىٰ يُحۡيِۦ هَٰذِهِ ٱللَّهُ بَعۡدَ مَوۡتِهَاۖ فَأَمَاتَهُ ٱللَّهُ مِاْئَةَ عَامٖ ثُمَّ بَعَثَهُۥۖ قَالَ كَمۡ لَبِثۡتَۖ قَالَ لَبِثۡتُ يَوۡمًا أَوۡ بَعۡضَ يَوۡمٖۖ قَالَ بَل لَّبِثۡتَ مِاْئَةَ عَامٖ فَٱنظُرۡ إِلَىٰ طَعَامِكَ وَشَرَابِكَ لَمۡ يَتَسَنَّهۡۖ وَٱنظُرۡ إِلَىٰ حِمَارِكَ وَلِنَجۡعَلَكَ ءَايَةٗ لِّلنَّاسِۖ وَٱنظُرۡ إِلَى ٱلۡعِظَامِ كَيۡفَ نُنشِزُهَا ثُمَّ نَكۡسُوهَا لَحۡمٗاۚ فَلَمَّا تَبَيَّنَ لَهُۥ قَالَ أَعۡلَمُ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","325":"۞ إِنَّ ٱللَّهَ ٱصۡطَفَىٰٓ ءَادَمَ وَنُوحٗا وَءَالَ إِبۡرَٰهِيمَ وَءَالَ عِمۡرَٰنَ عَلَى ٱلۡعَٰلَمِينَ","329":"فَتَقَبَّلَهَا رَبُّهَا بِقَبُولٍ حَسَنٖ وَأَنۢبَتَهَا نَبَاتًا حَسَنٗا وَكَفَّلَهَا زَكَرِيَّاۖ كُلَّمَا دَخَلَ عَلَيۡهَا زَكَرِيَّا ٱلۡمِحۡرَابَ وَجَدَ عِندَهَا رِزۡقٗاۖ قَالَ يَٰمَرۡيَمُ أَنَّىٰ لَكِ هَٰذَاۖ قَالَتۡ هُوَ مِنۡ عِندِ ٱللَّهِۖ إِنَّ ٱللَّهَ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٍ","330":"هُنَالِكَ دَعَا زَكَرِيَّا رَبَّهُۥۖ قَالَ رَبِّ هَبۡ لِي مِن لَّدُنكَ ذُرِّيَّةٗ طَيِّبَةًۖ إِنَّكَ سَمِيعُ ٱلدُّعَآءِ","331":"فَنَادَتۡهُ ٱلۡمَلَٰٓئِكَةُ وَهُوَ قَآئِمٞ يُصَلِّي فِي ٱلۡمِحۡرَابِ أَنَّ ٱللَّهَ يُبَشِّرُكَ بِيَحۡيَىٰ مُصَدِّقَۢا بِكَلِمَةٖ مِّنَ ٱللَّهِ وَسَيِّدٗا وَحَصُورٗا وَنَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ","337":"إِذۡ قَالَتِ ٱلۡمَلَٰٓئِكَةُ يَٰمَرۡيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٖ مِّنۡهُ ٱسۡمُهُ ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ وَجِيهٗا فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِ وَمِنَ ٱلۡمُقَرَّبِينَ","338":"وَيُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗا وَمِنَ ٱلصَّٰلِحِينَ","655":"۞ إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا","656":"وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا","778":"إِذۡ قَالَ ٱللَّهُ يَٰعِيسَى ٱبۡنَ مَرۡيَمَ ٱذۡكُرۡ نِعۡمَتِي عَلَيۡكَ وَعَلَىٰ وَٰلِدَتِكَ إِذۡ أَيَّدتُّكَ بِرُوحِ ٱلۡقُدُسِ تُكَلِّمُ ٱلنَّاسَ فِي ٱلۡمَهۡدِ وَكَهۡلٗاۖ وَإِذۡ عَلَّمۡتُكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَٱلتَّوۡرَىٰةَ وَٱلۡإِنجِيلَۖ وَإِذۡ تَخۡلُقُ مِنَ ٱلطِّينِ كَهَيۡـَٔةِ ٱلطَّيۡرِ بِإِذۡنِي فَتَنفُخُ فِيهَا فَتَكُونُ طَيۡرَۢا بِإِذۡنِيۖ وَتُبۡرِئُ ٱلۡأَكۡمَهَ وَٱلۡأَبۡرَصَ بِإِذۡنِيۖ وَإِذۡ تُخۡرِجُ ٱلۡمَوۡتَىٰ بِإِذۡنِيۖ وَإِذۡ كَفَفۡتُ بَنِيٓ إِسۡرَٰٓءِيلَ عَنكَ إِذۡ جِئۡتَهُم بِٱلۡبَيِّنَٰتِ فَقَالَ ٱلَّذِينَ كَفَرُواْ مِنۡهُمۡ إِنۡ هَٰذَآ إِلَّا سِحۡرٞ مُّبِينٞ","864":"فَلَمَّا جَنَّ عَلَيۡهِ ٱلَّيۡلُ رَءَا كَوۡكَبٗاۖ قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلۡأٓفِلِينَ","865":"فَلَمَّا رَءَا ٱلۡقَمَرَ بَازِغٗا قَالَ هَٰذَا رَبِّيۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمۡ يَهۡدِنِي رَبِّي لَأَكُونَنَّ مِنَ ٱلۡقَوۡمِ ٱلضَّآلِّينَ","866":"فَلَمَّا رَءَا ٱلشَّمۡسَ بَازِغَةٗ قَالَ هَٰذَا رَبِّي هَٰذَآ أَكۡبَرُۖ فَلَمَّآ أَفَلَتۡ قَالَ يَٰقَوۡمِ إِنِّي بَرِيٓءٞ مِّمَّا تُشۡرِكُونَ","867":"إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ","873":"وَزَكَرِيَّا وَيَحۡيَىٰ وَعِيسَىٰ وَإِلۡيَاسَۖ كُلّٞ مِّنَ ٱلصَّٰلِحِينَ","874":"وَإِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَيُونُسَ وَلُوطٗاۚ وَكُلّٗا فَضَّلۡنَا عَلَى ٱلۡعَٰلَمِينَ","877":"أُوْلَٰٓئِكَ ٱلَّذِينَ ءَاتَيۡنَٰهُمُ ٱلۡكِتَٰبَ وَٱلۡحُكۡمَ وَٱلنُّبُوَّةَۚ فَإِن يَكۡفُرۡ بِهَا هَٰٓؤُلَآءِ فَقَدۡ وَكَّلۡنَا بِهَا قَوۡمٗا لَّيۡسُواْ بِهَا بِكَٰفِرِينَ","1018":"۞ وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ","1019":"قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ","1026":"وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ","1027":"وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1033":"وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ","1034":"إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ","1038":"وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ","1039":"وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ","1096":"وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِيٓ أَنظُرۡ إِلَيۡكَۚ قَالَ لَن تَرَىٰنِي وَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ فَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ","1410":"وَلِكُلِّ أُمَّةٖ رَّسُولٞۖ فَإِذَا جَآءَ رَسُولُهُمۡ قُضِيَ بَيۡنَهُم بِٱلۡقِسۡطِ وَهُمۡ لَا يُظۡلَمُونَ","1536":"وَيَٰقَوۡمِ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٞ قَرِيبٞ","1537":"فَعَقَرُوهَا فَقَالَ تَمَتَّعُواْ فِي دَارِكُمۡ ثَلَٰثَةَ أَيَّامٖۖ ذَٰلِكَ وَعۡدٌ غَيۡرُ مَكۡذُوبٖ","1543":"وَٱمۡرَأَتُهُۥ قَآئِمَةٞ فَضَحِكَتۡ فَبَشَّرۡنَٰهَا بِإِسۡحَٰقَ وَمِن وَرَآءِ إِسۡحَٰقَ يَعۡقُوبَ","1544":"قَالَتۡ يَٰوَيۡلَتَىٰٓ ءَأَلِدُ وَأَنَا۠ عَجُوزٞ وَهَٰذَا بَعۡلِي شَيۡخًاۖ إِنَّ هَٰذَا لَشَيۡءٌ عَجِيبٞ","1545":"قَالُوٓاْ أَتَعۡجَبِينَ مِنۡ أَمۡرِ ٱللَّهِۖ رَحۡمَتُ ٱللَّهِ وَبَرَكَٰتُهُۥ عَلَيۡكُمۡ أَهۡلَ ٱلۡبَيۡتِۚ إِنَّهُۥ حَمِيدٞ مَّجِيدٞ","1549":"وَلَمَّا جَآءَتۡ رُسُلُنَا لُوطٗا سِيٓءَ بِهِمۡ وَضَاقَ بِهِمۡ ذَرۡعٗا وَقَالَ هَٰذَا يَوۡمٌ عَصِيبٞ","1550":"وَجَآءَهُۥ قَوۡمُهُۥ يُهۡرَعُونَ إِلَيۡهِ وَمِن قَبۡلُ كَانُواْ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِۚ قَالَ يَٰقَوۡمِ هَٰٓؤُلَآءِ بَنَاتِي هُنَّ أَطۡهَرُ لَكُمۡۖ فَٱتَّقُواْ ٱللَّهَ وَلَا تُخۡزُونِ فِي ضَيۡفِيٓۖ أَلَيۡسَ مِنكُمۡ رَجُلٞ رَّشِيدٞ","1551":"قَالُواْ لَقَدۡ عَلِمۡتَ مَا لَنَا فِي بَنَاتِكَ مِنۡ حَقّٖ وَإِنَّكَ لَتَعۡلَمُ مَا نُرِيدُ","1552":"قَالَ لَوۡ أَنَّ لِي بِكُمۡ قُوَّةً أَوۡ ءَاوِيٓ إِلَىٰ رُكۡنٖ شَدِيدٖ","1553":"قَالُواْ يَٰلُوطُ إِنَّا رُسُلُ رَبِّكَ لَن يَصِلُوٓاْ إِلَيۡكَۖ فَأَسۡرِ بِأَهۡلِكَ بِقِطۡعٖ مِّنَ ٱلَّيۡلِ وَلَا يَلۡتَفِتۡ مِنكُمۡ أَحَدٌ إِلَّا ٱمۡرَأَتَكَۖ إِنَّهُۥ مُصِيبُهَا مَآ أَصَابَهُمۡۚ إِنَّ مَوۡعِدَهُمُ ٱلصُّبۡحُۚ أَلَيۡسَ ٱلصُّبۡحُ بِقَرِيبٖ","1554":"فَلَمَّا جَآءَ أَمۡرُنَا جَعَلۡنَا عَٰلِيَهَا سَافِلَهَا وَأَمۡطَرۡنَا عَلَيۡهَا حِجَارَةٗ مِّن سِجِّيلٖ مَّنضُودٖ","1555":"مُّسَوَّمَةً عِندَ رَبِّكَۖ وَمَا هِيَ مِنَ ٱلظَّٰلِمِينَ بِبَعِيدٖ","1556":"۞ وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ وَلَا تَنقُصُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَۖ إِنِّيٓ أَرَىٰكُم بِخَيۡرٖ وَإِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٖ مُّحِيطٖ","1557":"وَيَٰقَوۡمِ أَوۡفُواْ ٱلۡمِكۡيَالَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ","1599":"إِذۡ قَالَ يُوسُفُ لِأَبِيهِ يَٰٓأَبَتِ إِنِّي رَأَيۡتُ أَحَدَ عَشَرَ كَوۡكَبٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ رَأَيۡتُهُمۡ لِي سَٰجِدِينَ","1600":"قَالَ يَٰبُنَيَّ لَا تَقۡصُصۡ رُءۡيَاكَ عَلَىٰٓ إِخۡوَتِكَ فَيَكِيدُواْ لَكَ كَيۡدًاۖ إِنَّ ٱلشَّيۡطَٰنَ لِلۡإِنسَٰنِ عَدُوّٞ مُّبِينٞ","1601":"وَكَذَٰلِكَ يَجۡتَبِيكَ رَبُّكَ وَيُعَلِّمُكَ مِن تَأۡوِيلِ ٱلۡأَحَادِيثِ وَيُتِمُّ نِعۡمَتَهُۥ عَلَيۡكَ وَعَلَىٰٓ ءَالِ يَعۡقُوبَ كَمَآ أَتَمَّهَا عَلَىٰٓ أَبَوَيۡكَ مِن قَبۡلُ إِبۡرَٰهِيمَ وَإِسۡحَٰقَۚ إِنَّ رَبَّكَ عَلِيمٌ حَكِيمٞ","1678":"قَالَ بَلۡ سَوَّلَتۡ لَكُمۡ أَنفُسُكُمۡ أَمۡرٗاۖ فَصَبۡرٞ جَمِيلٌۖ عَسَى ٱللَّهُ أَن يَأۡتِيَنِي بِهِمۡ جَمِيعًاۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","1679":"وَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰٓأَسَفَىٰ عَلَىٰ يُوسُفَ وَٱبۡيَضَّتۡ عَيۡنَاهُ مِنَ ٱلۡحُزۡنِ فَهُوَ كَظِيمٞ","1695":"وَرَفَعَ أَبَوَيۡهِ عَلَى ٱلۡعَرۡشِ وَخَرُّواْ لَهُۥ سُجَّدٗاۖ وَقَالَ يَٰٓأَبَتِ هَٰذَا تَأۡوِيلُ رُءۡيَٰيَ مِن قَبۡلُ قَدۡ جَعَلَهَا رَبِّي حَقّٗاۖ وَقَدۡ أَحۡسَنَ بِيٓ إِذۡ أَخۡرَجَنِي مِنَ ٱلسِّجۡنِ وَجَآءَ بِكُم مِّنَ ٱلۡبَدۡوِ مِنۢ بَعۡدِ أَن نَّزَغَ ٱلشَّيۡطَٰنُ بَيۡنِي وَبَيۡنَ إِخۡوَتِيٓۚ إِنَّ رَبِّي لَطِيفٞ لِّمَا يَشَآءُۚ إِنَّهُۥ هُوَ ٱلۡعَلِيمُ ٱلۡحَكِيمُ","1696":"۞ رَبِّ قَدۡ ءَاتَيۡتَنِي مِنَ ٱلۡمُلۡكِ وَعَلَّمۡتَنِي مِن تَأۡوِيلِ ٱلۡأَحَادِيثِۚ فَاطِرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ أَنتَ وَلِيِّۦ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ","1753":"وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوۡمِهِۦ لِيُبَيِّنَ لَهُمۡۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","1936":"وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ","2204":"فَوَجَدَا عَبۡدٗا مِّنۡ عِبَادِنَآ ءَاتَيۡنَٰهُ رَحۡمَةٗ مِّنۡ عِندِنَا وَعَلَّمۡنَٰهُ مِن لَّدُنَّا عِلۡمٗا","2222":"وَيَسۡـَٔلُونَكَ عَن ذِي ٱلۡقَرۡنَيۡنِۖ قُلۡ سَأَتۡلُواْ عَلَيۡكُم مِّنۡهُ ذِكۡرًا","2223":"إِنَّا مَكَّنَّا لَهُۥ فِي ٱلۡأَرۡضِ وَءَاتَيۡنَٰهُ مِن كُلِّ شَيۡءٖ سَبَبٗا","2251":"ذِكۡرُ رَحۡمَتِ رَبِّكَ عَبۡدَهُۥ زَكَرِيَّآ","2252":"إِذۡ نَادَىٰ رَبَّهُۥ نِدَآءً خَفِيّٗا","2253":"قَالَ رَبِّ إِنِّي وَهَنَ ٱلۡعَظۡمُ مِنِّي وَٱشۡتَعَلَ ٱلرَّأۡسُ شَيۡبٗا وَلَمۡ أَكُنۢ بِدُعَآئِكَ رَبِّ شَقِيّٗا","2254":"وَإِنِّي خِفۡتُ ٱلۡمَوَٰلِيَ مِن وَرَآءِي وَكَانَتِ ٱمۡرَأَتِي عَاقِرٗا فَهَبۡ لِي مِن لَّدُنكَ وَلِيّٗا","2255":"يَرِثُنِي وَيَرِثُ مِنۡ ءَالِ يَعۡقُوبَۖ وَٱجۡعَلۡهُ رَبِّ رَضِيّٗا","2261":"يَٰيَحۡيَىٰ خُذِ ٱلۡكِتَٰبَ بِقُوَّةٖۖ وَءَاتَيۡنَٰهُ ٱلۡحُكۡمَ صَبِيّٗا","2262":"وَحَنَانٗا مِّن لَّدُنَّا وَزَكَوٰةٗۖ وَكَانَ تَقِيّٗا","2263":"وَبَرَّۢا بِوَٰلِدَيۡهِ وَلَمۡ يَكُن جَبَّارًا عَصِيّٗا","2264":"وَسَلَٰمٌ عَلَيۡهِ يَوۡمَ وُلِدَ وَيَوۡمَ يَمُوتُ وَيَوۡمَ يُبۡعَثُ حَيّٗا","2279":"قَالَ إِنِّي عَبۡدُ ٱللَّهِ ءَاتَىٰنِيَ ٱلۡكِتَٰبَ وَجَعَلَنِي نَبِيّٗا","2280":"وَجَعَلَنِي مُبَارَكًا أَيۡنَ مَا كُنتُ وَأَوۡصَٰنِي بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمۡتُ حَيّٗا","2281":"وَبَرَّۢا بِوَٰلِدَتِي وَلَمۡ يَجۡعَلۡنِي جَبَّارٗا شَقِيّٗا","2282":"وَٱلسَّلَٰمُ عَلَيَّ يَوۡمَ وُلِدتُّ وَيَوۡمَ أَمُوتُ وَيَوۡمَ أُبۡعَثُ حَيّٗا","2290":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِبۡرَٰهِيمَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيًّا","2298":"فَلَمَّا ٱعۡتَزَلَهُمۡ وَمَا يَعۡبُدُونَ مِن دُونِ ٱللَّهِ وَهَبۡنَا لَهُۥٓ إِسۡحَٰقَ وَيَعۡقُوبَۖ وَكُلّٗا جَعَلۡنَا نَبِيّٗا","2300":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ مُوسَىٰٓۚ إِنَّهُۥ كَانَ مُخۡلَصٗا وَكَانَ رَسُولٗا نَّبِيّٗا","2302":"وَوَهَبۡنَا لَهُۥ مِن رَّحۡمَتِنَآ أَخَاهُ هَٰرُونَ نَبِيّٗا","2303":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِسۡمَٰعِيلَۚ إِنَّهُۥ كَانَ صَادِقَ ٱلۡوَعۡدِ وَكَانَ رَسُولٗا نَّبِيّٗا","2304":"وَكَانَ يَأۡمُرُ أَهۡلَهُۥ بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ وَكَانَ عِندَ رَبِّهِۦ مَرۡضِيّٗا","2305":"وَٱذۡكُرۡ فِي ٱلۡكِتَٰبِ إِدۡرِيسَۚ إِنَّهُۥ كَانَ صِدِّيقٗا نَّبِيّٗا","2306":"وَرَفَعۡنَٰهُ مَكَانًا عَلِيًّا","2356":"وَهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ","2357":"إِذۡ رَءَا نَارٗا فَقَالَ لِأَهۡلِهِ ٱمۡكُثُوٓاْ إِنِّيٓ ءَانَسۡتُ نَارٗا لَّعَلِّيٓ ءَاتِيكُم مِّنۡهَا بِقَبَسٍ أَوۡ أَجِدُ عَلَى ٱلنَّارِ هُدٗى","2358":"فَلَمَّآ أَتَىٰهَا نُودِيَ يَٰمُوسَىٰٓ","2359":"إِنِّيٓ أَنَا۠ رَبُّكَ فَٱخۡلَعۡ نَعۡلَيۡكَ إِنَّكَ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوٗى","2360":"وَأَنَا ٱخۡتَرۡتُكَ فَٱسۡتَمِعۡ لِمَا يُوحَىٰٓ","2361":"إِنَّنِيٓ أَنَا ٱللَّهُ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱعۡبُدۡنِي وَأَقِمِ ٱلصَّلَوٰةَ لِذِكۡرِيٓ","2376":"وَٱجۡعَل لِّي وَزِيرٗا مِّنۡ أَهۡلِي","2377":"هَٰرُونَ أَخِي","2378":"ٱشۡدُدۡ بِهِۦٓ أَزۡرِي","2379":"وَأَشۡرِكۡهُ فِيٓ أَمۡرِي","2468":"فَأَكَلَا مِنۡهَا فَبَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ","2469":"ثُمَّ ٱجۡتَبَٰهُ رَبُّهُۥ فَتَابَ عَلَيۡهِ وَهَدَىٰ","2550":"قَالُواْ حَرِّقُوهُ وَٱنصُرُوٓاْ ءَالِهَتَكُمۡ إِن كُنتُمۡ فَٰعِلِينَ","2551":"قُلۡنَا يَٰنَارُ كُونِي بَرۡدٗا وَسَلَٰمًا عَلَىٰٓ إِبۡرَٰهِيمَ","2565":"۞ وَأَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلضُّرُّ وَأَنتَ أَرۡحَمُ ٱلرَّٰحِمِينَ","2566":"فَٱسۡتَجَبۡنَا لَهُۥ فَكَشَفۡنَا مَا بِهِۦ مِن ضُرّٖۖ وَءَاتَيۡنَٰهُ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنۡ عِندِنَا وَذِكۡرَىٰ لِلۡعَٰبِدِينَ","2567":"وَإِسۡمَٰعِيلَ وَإِدۡرِيسَ وَذَا ٱلۡكِفۡلِۖ كُلّٞ مِّنَ ٱلصَّٰبِرِينَ","2568":"وَأَدۡخَلۡنَٰهُمۡ فِي رَحۡمَتِنَآۖ إِنَّهُم مِّنَ ٱلصَّٰلِحِينَ","2569":"وَذَا ٱلنُّونِ إِذ ذَّهَبَ مُغَٰضِبٗا فَظَنَّ أَن لَّن نَّقۡدِرَ عَلَيۡهِ فَنَادَىٰ فِي ٱلظُّلُمَٰتِ أَن لَّآ إِلَٰهَ إِلَّآ أَنتَ سُبۡحَٰنَكَ إِنِّي كُنتُ مِنَ ٱلظَّٰلِمِينَ","2570":"فَٱسۡتَجَبۡنَا لَهُۥ وَنَجَّيۡنَٰهُ مِنَ ٱلۡغَمِّۚ وَكَذَٰلِكَ نُـۨجِي ٱلۡمُؤۡمِنِينَ","2646":"وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ مِن رَّسُولٖ وَلَا نَبِيٍّ إِلَّآ إِذَا تَمَنَّىٰٓ أَلۡقَى ٱلشَّيۡطَٰنُ فِيٓ أُمۡنِيَّتِهِۦ فَيَنسَخُ ٱللَّهُ مَا يُلۡقِي ٱلشَّيۡطَٰنُ ثُمَّ يُحۡكِمُ ٱللَّهُ ءَايَٰتِهِۦۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","2947":"فَأۡتِيَا فِرۡعَوۡنَ فَقُولَآ إِنَّا رَسُولُ رَبِّ ٱلۡعَٰلَمِينَ","3038":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3056":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3074":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3093":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3109":"إِنِّي لَكُمۡ رَسُولٌ أَمِينٞ","3173":"وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ وَسُلَيۡمَٰنَ عِلۡمٗاۖ وَقَالَا ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي فَضَّلَنَا عَلَىٰ كَثِيرٖ مِّنۡ عِبَادِهِ ٱلۡمُؤۡمِنِينَ","3174":"وَوَرِثَ سُلَيۡمَٰنُ دَاوُۥدَۖ وَقَالَ يَٰٓأَيُّهَا ٱلنَّاسُ عُلِّمۡنَا مَنطِقَ ٱلطَّيۡرِ وَأُوتِينَا مِن كُلِّ شَيۡءٍۖ إِنَّ هَٰذَا لَهُوَ ٱلۡفَضۡلُ ٱلۡمُبِينُ","3258":"وَأَوۡحَيۡنَآ إِلَىٰٓ أُمِّ مُوسَىٰٓ أَنۡ أَرۡضِعِيهِۖ فَإِذَا خِفۡتِ عَلَيۡهِ فَأَلۡقِيهِ فِي ٱلۡيَمِّ وَلَا تَخَافِي وَلَا تَحۡزَنِيٓۖ إِنَّا رَآدُّوهُ إِلَيۡكِ وَجَاعِلُوهُ مِنَ ٱلۡمُرۡسَلِينَ","3259":"فَٱلۡتَقَطَهُۥٓ ءَالُ فِرۡعَوۡنَ لِيَكُونَ لَهُمۡ عَدُوّٗا وَحَزَنًاۗ إِنَّ فِرۡعَوۡنَ وَهَٰمَٰنَ وَجُنُودَهُمَا كَانُواْ خَٰطِـِٔينَ","3260":"وَقَالَتِ ٱمۡرَأَتُ فِرۡعَوۡنَ قُرَّتُ عَيۡنٖ لِّي وَلَكَۖ لَا تَقۡتُلُوهُ عَسَىٰٓ أَن يَنفَعَنَآ أَوۡ نَتَّخِذَهُۥ وَلَدٗا وَهُمۡ لَا يَشۡعُرُونَ","3353":"وَلَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَلَبِثَ فِيهِمۡ أَلۡفَ سَنَةٍ إِلَّا خَمۡسِينَ عَامٗا فَأَخَذَهُمُ ٱلطُّوفَانُ وَهُمۡ ظَٰلِمُونَ","3480":"وَلَقَدۡ ءَاتَيۡنَا لُقۡمَٰنَ ٱلۡحِكۡمَةَ أَنِ ٱشۡكُرۡ لِلَّهِۚ وَمَن يَشۡكُرۡ فَإِنَّمَا يَشۡكُرُ لِنَفۡسِهِۦۖ وَمَن كَفَرَ فَإِنَّ ٱللَّهَ غَنِيٌّ حَمِيدٞ","3539":"وَإِذۡ أَخَذۡنَا مِنَ ٱلنَّبِيِّـۧنَ مِيثَٰقَهُمۡ وَمِنكَ وَمِن نُّوحٖ وَإِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَى ٱبۡنِ مَرۡيَمَۖ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا","3572":"مَّا كَانَ مُحَمَّدٌ أَبَآ أَحَدٖ مِّن رِّجَالِكُمۡ وَلَٰكِن رَّسُولَ ٱللَّهِ وَخَاتَمَ ٱلنَّبِيِّـۧنَۗ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمٗا","3615":"۞ وَلَقَدۡ ءَاتَيۡنَا دَاوُۥدَ مِنَّا فَضۡلٗاۖ يَٰجِبَالُ أَوِّبِي مَعَهُۥ وَٱلطَّيۡرَۖ وَأَلَنَّا لَهُ ٱلۡحَدِيدَ","3616":"أَنِ ٱعۡمَلۡ سَٰبِغَٰتٖ وَقَدِّرۡ فِي ٱلسَّرۡدِۖ وَٱعۡمَلُواْ صَٰلِحًاۖ إِنِّي بِمَا تَعۡمَلُونَ بَصِيرٞ","3633":"وَمَآ أَرۡسَلۡنَٰكَ إِلَّا كَآفَّةٗ لِّلنَّاسِ بَشِيرٗا وَنَذِيرٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","3683":"إِنَّآ أَرۡسَلۡنَٰكَ بِٱلۡحَقِّ بَشِيرٗا وَنَذِيرٗاۚ وَإِن مِّنۡ أُمَّةٍ إِلَّا خَلَا فِيهَا نَذِيرٞ","3717":"وَٱضۡرِبۡ لَهُم مَّثَلًا أَصۡحَٰبَ ٱلۡقَرۡيَةِ إِذۡ جَآءَهَا ٱلۡمُرۡسَلُونَ","3718":"إِذۡ أَرۡسَلۡنَآ إِلَيۡهِمُ ٱثۡنَيۡنِ فَكَذَّبُوهُمَا فَعَزَّزۡنَا بِثَالِثٖ فَقَالُوٓاْ إِنَّآ إِلَيۡكُم مُّرۡسَلُونَ","3888":"فَبَشَّرۡنَٰهُ بِغُلَٰمٍ حَلِيمٖ","3889":"فَلَمَّا بَلَغَ مَعَهُ ٱلسَّعۡيَ قَالَ يَٰبُنَيَّ إِنِّيٓ أَرَىٰ فِي ٱلۡمَنَامِ أَنِّيٓ أَذۡبَحُكَ فَٱنظُرۡ مَاذَا تَرَىٰۚ قَالَ يَٰٓأَبَتِ ٱفۡعَلۡ مَا تُؤۡمَرُۖ سَتَجِدُنِيٓ إِن شَآءَ ٱللَّهُ مِنَ ٱلصَّٰبِرِينَ","3890":"فَلَمَّآ أَسۡلَمَا وَتَلَّهُۥ لِلۡجَبِينِ","3891":"وَنَٰدَيۡنَٰهُ أَن يَٰٓإِبۡرَٰهِيمُ","3892":"قَدۡ صَدَّقۡتَ ٱلرُّءۡيَآۚ إِنَّا كَذَٰلِكَ نَجۡزِي ٱلۡمُحۡسِنِينَ","3893":"إِنَّ هَٰذَا لَهُوَ ٱلۡبَلَٰٓؤُاْ ٱلۡمُبِينُ","3894":"وَفَدَيۡنَٰهُ بِذِبۡحٍ عَظِيمٖ","3899":"وَبَشَّرۡنَٰهُ بِإِسۡحَٰقَ نَبِيّٗا مِّنَ ٱلصَّٰلِحِينَ","3900":"وَبَٰرَكۡنَا عَلَيۡهِ وَعَلَىٰٓ إِسۡحَٰقَۚ وَمِن ذُرِّيَّتِهِمَا مُحۡسِنٞ وَظَالِمٞ لِّنَفۡسِهِۦ مُبِينٞ","3910":"وَإِنَّ إِلۡيَاسَ لَمِنَ ٱلۡمُرۡسَلِينَ","3911":"إِذۡ قَالَ لِقَوۡمِهِۦٓ أَلَا تَتَّقُونَ","3912":"أَتَدۡعُونَ بَعۡلٗا وَتَذَرُونَ أَحۡسَنَ ٱلۡخَٰلِقِينَ","3913":"ٱللَّهَ رَبَّكُمۡ وَرَبَّ ءَابَآئِكُمُ ٱلۡأَوَّلِينَ","3926":"وَإِنَّ يُونُسَ لَمِنَ ٱلۡمُرۡسَلِينَ","3927":"إِذۡ أَبَقَ إِلَى ٱلۡفُلۡكِ ٱلۡمَشۡحُونِ","3928":"فَسَاهَمَ فَكَانَ مِنَ ٱلۡمُدۡحَضِينَ","3929":"فَٱلۡتَقَمَهُ ٱلۡحُوتُ وَهُوَ مُلِيمٞ","3930":"فَلَوۡلَآ أَنَّهُۥ كَانَ مِنَ ٱلۡمُسَبِّحِينَ","3931":"لَلَبِثَ فِي بَطۡنِهِۦٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ","3932":"۞ فَنَبَذۡنَٰهُ بِٱلۡعَرَآءِ وَهُوَ سَقِيمٞ","3933":"وَأَنۢبَتۡنَا عَلَيۡهِ شَجَرَةٗ مِّن يَقۡطِينٖ","3934":"وَأَرۡسَلۡنَٰهُ إِلَىٰ مِاْئَةِ أَلۡفٍ أَوۡ يَزِيدُونَ","3935":"فَـَٔامَنُواْ فَمَتَّعۡنَٰهُمۡ إِلَىٰ حِينٖ","3986":"ٱصۡبِرۡ عَلَىٰ مَا يَقُولُونَ وَٱذۡكُرۡ عَبۡدَنَا دَاوُۥدَ ذَا ٱلۡأَيۡدِۖ إِنَّهُۥٓ أَوَّابٌ","3987":"إِنَّا سَخَّرۡنَا ٱلۡجِبَالَ مَعَهُۥ يُسَبِّحۡنَ بِٱلۡعَشِيِّ وَٱلۡإِشۡرَاقِ","3988":"وَٱلطَّيۡرَ مَحۡشُورَةٗۖ كُلّٞ لَّهُۥٓ أَوَّابٞ","3989":"وَشَدَدۡنَا مُلۡكَهُۥ وَءَاتَيۡنَٰهُ ٱلۡحِكۡمَةَ وَفَصۡلَ ٱلۡخِطَابِ","4004":"قَالَ رَبِّ ٱغۡفِرۡ لِي وَهَبۡ لِي مُلۡكٗا لَّا يَنۢبَغِي لِأَحَدٖ مِّنۢ بَعۡدِيٓۖ إِنَّكَ أَنتَ ٱلۡوَهَّابُ","4005":"فَسَخَّرۡنَا لَهُ ٱلرِّيحَ تَجۡرِي بِأَمۡرِهِۦ رُخَآءً حَيۡثُ أَصَابَ","4006":"وَٱلشَّيَٰطِينَ كُلَّ بَنَّآءٖ وَغَوَّاصٖ","4007":"وَءَاخَرِينَ مُقَرَّنِينَ فِي ٱلۡأَصۡفَادِ","4010":"وَٱذۡكُرۡ عَبۡدَنَآ أَيُّوبَ إِذۡ نَادَىٰ رَبَّهُۥٓ أَنِّي مَسَّنِيَ ٱلشَّيۡطَٰنُ بِنُصۡبٖ وَعَذَابٍ","4011":"ٱرۡكُضۡ بِرِجۡلِكَۖ هَٰذَا مُغۡتَسَلُۢ بَارِدٞ وَشَرَابٞ","4012":"وَوَهَبۡنَا لَهُۥٓ أَهۡلَهُۥ وَمِثۡلَهُم مَّعَهُمۡ رَحۡمَةٗ مِّنَّا وَذِكۡرَىٰ لِأُوْلِي ٱلۡأَلۡبَٰبِ","4013":"وَخُذۡ بِيَدِكَ ضِغۡثٗا فَٱضۡرِب بِّهِۦ وَلَا تَحۡنَثۡۗ إِنَّا وَجَدۡنَٰهُ صَابِرٗاۚ نِّعۡمَ ٱلۡعَبۡدُ إِنَّهُۥٓ أَوَّابٞ","4017":"وَٱذۡكُرۡ إِسۡمَٰعِيلَ وَٱلۡيَسَعَ وَذَا ٱلۡكِفۡلِۖ وَكُلّٞ مِّنَ ٱلۡأَخۡيَارِ","4166":"وَلَقَدۡ جَآءَكُمۡ يُوسُفُ مِن قَبۡلُ بِٱلۡبَيِّنَٰتِ فَمَا زِلۡتُمۡ فِي شَكّٖ مِّمَّا جَآءَكُم بِهِۦۖ حَتَّىٰٓ إِذَا هَلَكَ قُلۡتُمۡ لَن يَبۡعَثَ ٱللَّهُ مِنۢ بَعۡدِهِۦ رَسُولٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَنۡ هُوَ مُسۡرِفٞ مُّرۡتَابٌ","4210":"وَلَقَدۡ أَرۡسَلۡنَا رُسُلٗا مِّن قَبۡلِكَ مِنۡهُم مَّن قَصَصۡنَا عَلَيۡكَ وَمِنۡهُم مَّن لَّمۡ نَقۡصُصۡ عَلَيۡكَۗ وَمَا كَانَ لِرَسُولٍ أَن يَأۡتِيَ بِـَٔايَةٍ إِلَّا بِإِذۡنِ ٱللَّهِۚ فَإِذَا جَآءَ أَمۡرُ ٱللَّهِ قُضِيَ بِٱلۡحَقِّ وَخَسِرَ هُنَالِكَ ٱلۡمُبۡطِلُونَ","4284":"۞ شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحٗا وَٱلَّذِيٓ أَوۡحَيۡنَآ إِلَيۡكَ وَمَا وَصَّيۡنَا بِهِۦٓ إِبۡرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓۖ أَنۡ أَقِيمُواْ ٱلدِّينَ وَلَا تَتَفَرَّقُواْ فِيهِۚ كَبُرَ عَلَى ٱلۡمُشۡرِكِينَ مَا تَدۡعُوهُمۡ إِلَيۡهِۚ ٱللَّهُ يَجۡتَبِيٓ إِلَيۡهِ مَن يَشَآءُ وَيَهۡدِيٓ إِلَيۡهِ مَن يُنِيبُ","4530":"۞ وَٱذۡكُرۡ أَخَا عَادٍ إِذۡ أَنذَرَ قَوۡمَهُۥ بِٱلۡأَحۡقَافِ وَقَدۡ خَلَتِ ٱلنُّذُرُ مِنۢ بَيۡنِ يَدَيۡهِ وَمِنۡ خَلۡفِهِۦٓ أَلَّا تَعۡبُدُوٓاْ إِلَّا ٱللَّهَ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ","4531":"قَالُوٓاْ أَجِئۡتَنَا لِتَأۡفِكَنَا عَنۡ ءَالِهَتِنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ","4544":"فَٱصۡبِرۡ كَمَا صَبَرَ أُوْلُواْ ٱلۡعَزۡمِ مِنَ ٱلرُّسُلِ وَلَا تَسۡتَعۡجِل لَّهُمۡۚ كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَ مَا يُوعَدُونَ لَمۡ يَلۡبَثُوٓاْ إِلَّا سَاعَةٗ مِّن نَّهَارِۭۚ بَلَٰغٞۚ فَهَلۡ يُهۡلَكُ إِلَّا ٱلۡقَوۡمُ ٱلۡفَٰسِقُونَ","4611":"مُّحَمَّدٞ رَّسُولُ ٱللَّهِۚ وَٱلَّذِينَ مَعَهُۥٓ أَشِدَّآءُ عَلَى ٱلۡكُفَّارِ رُحَمَآءُ بَيۡنَهُمۡۖ تَرَىٰهُمۡ رُكَّعٗا سُجَّدٗا يَبۡتَغُونَ فَضۡلٗا مِّنَ ٱللَّهِ وَرِضۡوَٰنٗاۖ سِيمَاهُمۡ فِي وُجُوهِهِم مِّنۡ أَثَرِ ٱلسُّجُودِۚ ذَٰلِكَ مَثَلُهُمۡ فِي ٱلتَّوۡرَىٰةِۚ وَمَثَلُهُمۡ فِي ٱلۡإِنجِيلِ كَزَرۡعٍ أَخۡرَجَ شَطۡـَٔهُۥ فَـَٔازَرَهُۥ فَٱسۡتَغۡلَظَ فَٱسۡتَوَىٰ عَلَىٰ سُوقِهِۦ يُعۡجِبُ ٱلزُّرَّاعَ لِيَغِيظَ بِهِمُ ٱلۡكُفَّارَۗ وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ مِنۡهُم مَّغۡفِرَةٗ وَأَجۡرًا عَظِيمَۢا","5168":"وَإِذۡ قَالَ عِيسَى ٱبۡنُ مَرۡيَمَ يَٰبَنِيٓ إِسۡرَٰٓءِيلَ إِنِّي رَسُولُ ٱللَّهِ إِلَيۡكُم مُّصَدِّقٗا لِّمَا بَيۡنَ يَدَيَّ مِنَ ٱلتَّوۡرَىٰةِ وَمُبَشِّرَۢا بِرَسُولٖ يَأۡتِي مِنۢ بَعۡدِي ٱسۡمُهُۥٓ أَحۡمَدُۖ فَلَمَّا جَآءَهُم بِٱلۡبَيِّنَٰتِ قَالُواْ هَٰذَا سِحۡرٞ مُّبِينٞ","5419":"إِنَّآ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦٓ أَنۡ أَنذِرۡ قَوۡمَكَ مِن قَبۡلِ أَن يَأۡتِيَهُمۡ عَذَابٌ أَلِيمٞ","5420":"قَالَ يَٰقَوۡمِ إِنِّي لَكُمۡ نَذِيرٞ مُّبِينٌ","5421":"أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱتَّقُوهُ وَأَطِيعُونِ","5422":"يَغۡفِرۡ لَكُم مِّن ذُنُوبِكُمۡ وَيُؤَخِّرۡكُمۡ إِلَىٰٓ أَجَلٖ مُّسَمًّىۚ إِنَّ أَجَلَ ٱللَّهِ إِذَا جَآءَ لَا يُؤَخَّرُۚ لَوۡ كُنتُمۡ تَعۡلَمُونَ"},"nay":164};
